import { Image } from '@wix/wix-ui-icons-common/lazy';

import type { AddButton, RicosServices } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_IMAGE_BUTTON } from './data-hooks.js';
import { handleImageUpload } from './handle-image-upload.js';
import type { ImagePluginEditorConfig } from './types.js';

export const imageAddToolbars: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.MOBILE,
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
];

export const getAddButtons = (
  config: ImagePluginEditorConfig,
  services: RicosServices
): AddButton[] => {
  return [
    {
      id: Node_Type.IMAGE,
      label: INSERT_PLUGIN_BUTTONS.IMAGE,
      dataHook: INSERT_IMAGE_BUTTON,
      icon: Image,
      tooltip: 'ImagePlugin_InsertButton_Tooltip',
      toolbars: imageAddToolbars,

      command: ({ publicCommands, referenceElement }) => {
        if (!services) {
          return false;
        }
        handleImageUpload({
          services,
          config,
          publicCommands,
          referenceElement: referenceElement ?? undefined,
        });
        return true;
      },
      menuConfig: {
        tags: 'Image_plugin_search_tags',
      },
    },
  ];
};
