import { Tooltip } from '@wix/design-system';
import { Revert } from '@wix/wix-ui-icons-common/lazy';
import cx from 'classnames';
import React, { forwardRef, useCallback, useContext, useEffect, useRef, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { useModalService } from './../../ricos-modals/modal-service-provider.js';
import { PluginContainerData_Width_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ImageData_Crop, ImageData_CropShape } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { isCropped, toCropAttribute } from './../../_shared/media/image-crop.js';
import type { Transaction } from './../../tiptap/pm/state.js';

import { CornerRadiusHandles } from '../components/corner-radius-handles.js';
import { CropEdgeHandles, type CropEdgeChange } from '../components/crop-edge-handles.js';
import { IMAGE_BUTTONS } from '../consts.js';
import { IMAGE_CROP_MODE_META, type ImageCropModeMeta } from '../crop-mode-meta.js';
import {
  CropOverlay,
  type CropApply,
  type CropOverlayHandle,
} from '../crop-overlay/crop-overlay.js';
import classes from '../statics/styles/image-viewer-scss.js';
import {
  resolveCropFrameAspectRatio,
  type CropFramePresetId,
  type CropPresetId,
  type CropPresetOption,
} from '../toolbar/crop-presets.js';
import {
  createStaticImagePanelReferenceElement,
  resolveImageDoubleClickPanelReferenceElement,
} from '../toolbar/resolve-image-plugin-panel-reference-element.js';
import { ShapeCropModal } from '../toolbar/shape-crop-modal.js';
import { getShapeCrop, isShapeCropModalInteractionTarget } from '../toolbar/shape-crop.js';

// Preset sizes are kept through cropping; CONTENT/custom take a scale-preserving custom width.
const isPresetWidthSize = (size: PluginContainerData_Width_Type | undefined): boolean =>
  size === PluginContainerData_Width_Type.SMALL ||
  size === PluginContainerData_Width_Type.ORIGINAL ||
  size === PluginContainerData_Width_Type.FULL_WIDTH;

const areCropsEqual = (left: ImageData_Crop | null, right: ImageData_Crop | null): boolean =>
  left === right ||
  (left !== null &&
    right !== null &&
    left.x === right.x &&
    left.y === right.y &&
    left.width === right.width &&
    left.height === right.height);

type ResetButtonMode = 'full' | 'icon-only' | 'hidden';

type UseImageControlsArgs = {
  containerRef: React.RefObject<HTMLDivElement | null>;
  editor: PluginProps['editor'];
  nodeAttrs: PluginProps['node']['attrs'];
  selected: boolean;
  isHovering: boolean;
  isMobile: boolean;
  imageSrc: string | undefined;
  loading: boolean;
  error: PluginProps['node']['attrs']['error'];
  updateAttributes: PluginProps['updateAttributes'];
};

type ResetButtonContentProps = {
  isIconOnly: boolean;
  label: string;
  dataHook?: string;
  onClick?: () => void;
};

const ResetButtonContent = forwardRef<HTMLButtonElement, ResetButtonContentProps>(
  ({ isIconOnly, label, dataHook, onClick }, ref) => (
    <button
      ref={ref}
      type="button"
      className={cx(classes.cropResetButtonInner, { [classes.iconOnly]: isIconOnly })}
      onClick={onClick}
      data-hook={dataHook}
      aria-label={label}
    >
      <Revert className={classes.cropResetIcon} />
      {!isIconOnly && label}
    </button>
  )
);
ResetButtonContent.displayName = 'ResetButtonContent';

export const useImageControls = ({
  containerRef,
  editor,
  nodeAttrs,
  selected,
  isHovering,
  isMobile,
  imageSrc,
  loading,
  error,
  updateAttributes,
}: UseImageControlsArgs): {
  cropMode: boolean;
  enterCropMode: () => void;
  imageControls: React.ReactNode;
} => {
  const { t, jsdomMode, environment, portal } = useContext(RicosContext);
  const modalService = useModalService();
  const [isDraggingHandle, setIsDraggingHandle] = useState(false);
  const [cropMode, setCropMode] = useState(false);
  const [resetButtonMode, setResetButtonMode] = useState<ResetButtonMode>(() =>
    jsdomMode ? 'full' : 'hidden'
  );
  const [resetButtonDimensions, setResetButtonDimensions] = useState<{
    fullWidth: number;
    iconWidth: number;
  } | null>(null);
  const [cropFrameAspectRatio, setCropFrameAspectRatio] = useState<number | null>(null);
  const [selectedCropFramePresetId, setSelectedCropFramePresetId] =
    useState<CropFramePresetId>('FRAME_FREE_FORM');
  const [draftCropShape, setDraftCropShape] = useState<ImageData_CropShape | null | undefined>();
  const resetFullButtonRef = useRef<HTMLButtonElement>(null);
  const resetIconOnlyButtonRef = useRef<HTMLButtonElement>(null);
  const cropOverlayRef = useRef<CropOverlayHandle>(null);
  const [isShapeCropModalOpen, setIsShapeCropModalOpen] = useState(false);

  const currentRadius = nodeAttrs.styles?.border?.radius ?? 0;
  const currentCrop: ImageData_Crop | null = nodeAttrs.crop ?? null;
  const currentCropShape = getShapeCrop(nodeAttrs);
  const hasCustomWidth = !!nodeAttrs.containerData?.width?.custom;
  const hasShapeCrop = Boolean(currentCropShape);
  const previewCropShape = draftCropShape === undefined ? currentCropShape : draftCropShape;
  const hasChanges = isCropped(currentCrop) || hasCustomWidth || hasShapeCrop;
  const canCrop = Boolean(imageSrc) && !loading && !error && !isMobile;
  const cropOverlayAspectRatio = previewCropShape ? 1 : cropFrameAspectRatio;
  const selectedCropPresetId: CropPresetId = currentCropShape ?? selectedCropFramePresetId;
  const shouldShowResetButton = selected && !isMobile && !cropMode && isHovering && hasChanges;

  const closeShapeCropModal = useCallback(() => {
    if (modalService.isModalOpen(IMAGE_BUTTONS.shapeCrop)) {
      modalService.closeModal(IMAGE_BUTTONS.shapeCrop);
    }
  }, [modalService]);

  const enableCropMode = useCallback((): boolean => {
    if (!canCrop) {
      return false;
    }
    setCropMode(true);
    return true;
  }, [canCrop]);

  const exitCropMode = useCallback(() => {
    setCropMode(false);
    setDraftCropShape(undefined);
    closeShapeCropModal();
  }, [closeShapeCropModal]);

  const handleReset = useCallback(() => {
    updateAttributes({
      crop: null,
      cropShape: null,
      ...(hasCustomWidth
        ? {
            containerData: {
              ...nodeAttrs.containerData,
              width: { size: PluginContainerData_Width_Type.CONTENT },
              height: undefined,
            },
          }
        : {}),
    });
  }, [updateAttributes, hasCustomWidth, nodeAttrs.containerData]);

  const handleRadiusChange = useCallback(
    (radius: number) => {
      updateAttributes({
        styles: {
          ...nodeAttrs.styles,
          border: {
            ...nodeAttrs.styles?.border,
            radius,
          },
        },
      });
    },
    [nodeAttrs.styles, updateAttributes]
  );

  const handleEdgeChange = useCallback(
    ({ crop, widthPx }: CropEdgeChange) => {
      const keepPresetSize = isPresetWidthSize(nodeAttrs.containerData?.width?.size);
      updateAttributes({
        crop: toCropAttribute(crop),
        ...(widthPx !== undefined && !keepPresetSize
          ? { containerData: { ...nodeAttrs.containerData, width: { custom: widthPx } } }
          : {}),
      });
    },
    [updateAttributes, nodeAttrs.containerData]
  );

  const handleCropApply = useCallback(
    ({ crop, widthPx }: CropApply) => {
      const keepPresetSize = isPresetWidthSize(nodeAttrs.containerData?.width?.size);
      const nextCrop = toCropAttribute(crop);
      const nextCropShape = draftCropShape === undefined ? currentCropShape : draftCropShape;
      const keepCurrentWidth =
        widthPx === undefined ||
        keepPresetSize ||
        (areCropsEqual(toCropAttribute(currentCrop), nextCrop) &&
          currentCropShape === nextCropShape);

      updateAttributes({
        crop: nextCrop,
        ...(draftCropShape === undefined ? {} : { cropShape: draftCropShape }),
        ...(keepCurrentWidth
          ? {}
          : { containerData: { ...nodeAttrs.containerData, width: { custom: widthPx } } }),
      });
      exitCropMode();
    },
    [
      currentCrop,
      currentCropShape,
      draftCropShape,
      exitCropMode,
      updateAttributes,
      nodeAttrs.containerData,
    ]
  );

  const handleCropPresetApply = useCallback(
    (preset: CropPresetOption) => {
      if (preset.kind === 'shape') {
        setCropFrameAspectRatio(1);
        setDraftCropShape(preset.id);
        enableCropMode();
        return;
      }

      setSelectedCropFramePresetId(preset.id);
      setCropFrameAspectRatio(
        resolveCropFrameAspectRatio(preset, nodeAttrs.image?.width, nodeAttrs.image?.height)
      );
      setDraftCropShape(null);
      enableCropMode();
    },
    [enableCropMode, nodeAttrs.image?.height, nodeAttrs.image?.width]
  );

  const applyActiveCrop = useCallback(() => {
    if (cropOverlayRef.current?.apply()) {
      return;
    }

    exitCropMode();
  }, [exitCropMode]);

  const cancelActiveCrop = useCallback(() => {
    if (cropOverlayRef.current) {
      cropOverlayRef.current.cancel();
      return;
    }

    exitCropMode();
  }, [exitCropMode]);

  useEffect(() => {
    if (!shouldShowResetButton || resetButtonDimensions) {
      return;
    }

    const fullWidth = resetFullButtonRef.current?.offsetWidth;
    const iconWidth = resetIconOnlyButtonRef.current?.offsetWidth;

    if (!fullWidth || !iconWidth) {
      return;
    }

    setResetButtonDimensions({ fullWidth, iconWidth });
  }, [resetButtonDimensions, shouldShowResetButton]);

  useEffect(() => {
    if (!shouldShowResetButton) {
      setResetButtonMode('hidden');
      return;
    }

    if (!containerRef.current || !resetButtonDimensions || jsdomMode) {
      return;
    }

    const container = containerRef.current;
    const checkButtonFit = () => {
      const horizontalPadding = 16;
      const chromeWidth = 6;
      const availableWidth = container.offsetWidth - horizontalPadding;
      const canFitFull = resetButtonDimensions.fullWidth + chromeWidth <= availableWidth;
      const canFitIcon = resetButtonDimensions.iconWidth + chromeWidth <= availableWidth;
      const hasEnoughHeight = container.offsetHeight >= 36;

      if (canFitFull && hasEnoughHeight) {
        setResetButtonMode('full');
      } else if (canFitIcon && hasEnoughHeight) {
        setResetButtonMode('icon-only');
      } else {
        setResetButtonMode('hidden');
      }
    };

    checkButtonFit();

    const resizeObserver = new ResizeObserver(checkButtonFit);
    resizeObserver.observe(container);

    return () => {
      resizeObserver.disconnect();
    };
  }, [containerRef, jsdomMode, resetButtonDimensions, shouldShowResetButton]);

  const enterCropMode = useCallback(() => {
    const referenceElement = containerRef.current;
    if (
      !referenceElement ||
      isShapeCropModalOpen ||
      modalService.isModalOpen(IMAGE_BUTTONS.shapeCrop)
    ) {
      return;
    }

    const panelReferenceElement = createStaticImagePanelReferenceElement(
      resolveImageDoubleClickPanelReferenceElement({
        referenceElement,
        environment,
        portal,
      })
    );

    if (!enableCropMode()) {
      return;
    }

    modalService.togglePluginPanel({
      id: IMAGE_BUTTONS.shapeCrop,
      Component: ShapeCropModal,
      isMobile,
      componentProps: {
        selectedId: selectedCropPresetId,
        onApply: handleCropPresetApply,
        onApplyCrop: applyActiveCrop,
        onCancelCrop: cancelActiveCrop,
      },
      positioning: {
        referenceElement: panelReferenceElement,
        placement: 'right-start',
      },
      onClickOutside: {
        on: 'pointerup',
        handler: event => {
          if (!isShapeCropModalInteractionTarget(event.target, referenceElement)) {
            exitCropMode();
          }
        },
      },
      focusReturnElement: referenceElement,
    });
    setIsShapeCropModalOpen(true);
  }, [
    applyActiveCrop,
    cancelActiveCrop,
    containerRef,
    enableCropMode,
    exitCropMode,
    handleCropPresetApply,
    isShapeCropModalOpen,
    isMobile,
    modalService,
    selectedCropPresetId,
    environment,
    portal,
  ]);

  useEffect(() => {
    const onTransaction = ({ transaction }: { transaction: Transaction }) => {
      const meta = transaction.getMeta(IMAGE_CROP_MODE_META) as ImageCropModeMeta | undefined;
      if (!meta || meta.nodeId !== nodeAttrs.id) {
        return;
      }

      enterCropMode();
    };

    editor.on('transaction', onTransaction);

    return () => {
      editor.off('transaction', onTransaction);
    };
  }, [editor, enterCropMode, nodeAttrs.id]);

  useEffect(() => {
    const subscription = modalService.onModalClosed(modal => {
      if (modal.id === IMAGE_BUTTONS.shapeCrop) {
        setIsShapeCropModalOpen(false);
        setCropMode(false);
        setDraftCropShape(undefined);
      }
    });

    return () => subscription.cancel();
  }, [modalService]);

  useEffect(() => {
    if (cropMode && !selected && !isShapeCropModalOpen) {
      setCropMode(false);
      setDraftCropShape(undefined);
    }
  }, [cropMode, isShapeCropModalOpen, selected]);

  useEffect(() => {
    if (!isShapeCropModalOpen || cropMode) {
      return;
    }

    if (!enableCropMode()) {
      closeShapeCropModal();
    }
  }, [closeShapeCropModal, cropMode, enableCropMode, isShapeCropModalOpen]);

  useEffect(() => {
    if (!cropMode) {
      return;
    }

    const figure = containerRef.current?.closest('[data-hook^="figure-"]');
    figure?.setAttribute('data-cropping', 'true');
    editor.view.dispatch(editor.state.tr.setMeta('forceToolbarUpdate', true));

    return () => {
      figure?.removeAttribute('data-cropping');
      editor.view.dispatch(editor.state.tr.setMeta('forceToolbarUpdate', true));
    };
  }, [containerRef, cropMode, editor]);

  const imageControls = (
    <>
      {selected && !isMobile && !cropMode && !hasShapeCrop && (
        <CropEdgeHandles
          containerRef={containerRef}
          crop={currentCrop}
          alignment={nodeAttrs.containerData?.alignment}
          onChange={handleEdgeChange}
          onDraggingChange={setIsDraggingHandle}
        />
      )}
      {shouldShowResetButton && !resetButtonDimensions && (
        <div className={classes.cropResetMeasurement} aria-hidden="true" role="presentation">
          <ResetButtonContent
            ref={resetFullButtonRef}
            isIconOnly={false}
            label={t('ImageReset_Label')}
          />
          <ResetButtonContent
            ref={resetIconOnlyButtonRef}
            isIconOnly
            label={t('ImageReset_Label')}
          />
        </div>
      )}
      {shouldShowResetButton && resetButtonMode !== 'hidden' && (
        <div className={classes.cropResetButton} contentEditable={false}>
          {resetButtonMode === 'icon-only' ? (
            <Tooltip content={t('ImageReset_Label')} size="small" appendTo={portal}>
              <ResetButtonContent
                isIconOnly
                label={t('ImageReset_Label')}
                dataHook="image-reset-changes"
                onClick={handleReset}
              />
            </Tooltip>
          ) : (
            <ResetButtonContent
              isIconOnly={false}
              label={t('ImageReset_Label')}
              dataHook="image-reset-changes"
              onClick={handleReset}
            />
          )}
        </div>
      )}
      {selected && !cropMode && !hasShapeCrop && (isHovering || isDraggingHandle) && (
        <CornerRadiusHandles
          containerRef={containerRef}
          currentRadius={currentRadius}
          onRadiusChange={handleRadiusChange}
          onDraggingChange={setIsDraggingHandle}
        />
      )}
      {cropMode && imageSrc && (
        <CropOverlay
          actionsRef={cropOverlayRef}
          containerRef={containerRef}
          imageSrc={imageSrc}
          crop={currentCrop}
          cropShape={previewCropShape}
          aspectRatio={cropOverlayAspectRatio}
          onApply={handleCropApply}
          onCancel={exitCropMode}
        />
      )}
    </>
  );

  return { cropMode, enterCropMode, imageControls };
};
