import type { ImageComponentData } from './../ricos-content/index.js';
import { IMAGE_TYPE } from './../ricos-content/index.js';
import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import type { PublicCommands } from './../ricos-types/index.js';
import type { MediaUploadFn } from './../_shared/create-media-upload-fn.js';
import { createMediaUploadFn } from './../_shared/create-media-upload-fn.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { createImageFileSelectionFn } from './../_shared/media-manager/create-image-file-selection-fn.js';
import type { PickMediaFn } from './../_shared/media/pick-media.js';
import type { PickMediaImageData, PublicPickMedia } from './../_shared/media/public-pick-media.js';
import type { PmImageNode } from './../_shared/pm-node-types.js';
import { unreachable } from './../_shared/uncreachable.js';
import { upload } from './../_shared/upload/upload.js';

import { RICOS_DEFAULTS } from './consts.js';
import type { ImagePluginEditorConfig } from './types.js';

const getImagePickMedia = ({
  services,
  handleFileUpload,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  handleFileUpload: MediaUploadFn;
}): PickMediaFn | PublicPickMedia['pickImage'] => {
  const devPickMedia = services.devService().pickMedia;
  const editorPickMedia = services.editorProps.pickMedia?.pickImage;
  const handleFileSelection =
    services.devService().handleFileSelection ?? createImageFileSelectionFn(services);

  return devPickMedia
    ? devPickMedia
    : editorPickMedia
      ? editorPickMedia
      : handleFileSelection
        ? async ({ multiple }: Parameters<PickMediaFn>[0]) => {
            try {
              const data = await new Promise<ImageComponentData[]>((resolve, reject) =>
                handleFileSelection(
                  ({ data }) => resolve(data),
                  { multiple, index: undefined },
                  reject
                )
              );
              return { type: 'ready-media' as const, media: data };
            } catch {
              return { type: 'cancel' as const };
            }
          }
        : async ({ mimeType, multiple }: Parameters<PickMediaFn>[0]) => {
            const files =
              (await services.uploadService?.selectFiles({ accept: mimeType, multiple })) ?? [];
            return { type: 'file' as const, file: files, customUploadFn: handleFileUpload };
          };
};

export const handleImageUpload = async ({
  services,
  config,
  publicCommands,
  nodeId,
  files,
  pos,
  referenceElement,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  config: ImagePluginEditorConfig;
  publicCommands: PublicCommands;
  nodeId?: string;
  files?: File[];
  pos?: number;
  referenceElement?: HTMLElement;
}) => {
  const { accept = 'image/*', multi = true } = config;

  const multiple = nodeId ? false : multi;
  const handleFileUpload = services.devService().handleFileUpload ?? createMediaUploadFn(services);

  const pickMedia = getImagePickMedia({ services, handleFileUpload });

  const result = files
    ? {
        type: 'file' as const,
        file: files,
        customUploadFn: handleFileUpload,
      }
    : await pickMedia({ mimeType: accept, multiple });

  switch (result.type) {
    case 'ready-media': {
      if (nodeId) {
        const componentData: PmImageNode['attrs'] = publicCommands?.getBlockComponentData(nodeId);

        const image = (result.media[0] as ImageComponentData | PickMediaImageData) || {};
        publicCommands?.setBlock(nodeId, IMAGE_TYPE, {
          ...componentData,
          image: getImageData(image),
          tempData: null,
          loading: null,
          error: null,
        } satisfies PmImageNode['attrs']);
        return;
      }

      result.media.forEach((item, index) => {
        setTimeout(() => {
          const image = item as ImageComponentData | PickMediaImageData;
          publicCommands.insertBlockWithBlankLines(
            IMAGE_TYPE,
            { image: getImageData(image), ...RICOS_DEFAULTS },
            {
              updateSelection: result.media.length === index + 1,
            }
          );
        });
      });
      return;
    }
    case 'file': {
      const resultFiles = result.file;

      return resultFiles.map(async (file, index) => {
        // this can be executed inside tiptap command (when pasting) so we need to schedule file handling.
        setTimeout(async () => {
          const targetNodeId =
            nodeId ??
            publicCommands.insertBlockWithBlankLines(
              IMAGE_TYPE,
              { ...RICOS_DEFAULTS, loading: true },
              {
                updateSelection: resultFiles.length === index + 1,
                pos,
              }
            );

          const trackBi = services.uploadService.trackUploadBi(IMAGE_TYPE, file.size, file.name);
          try {
            const url = URL.createObjectURL(file);
            await Promise.resolve();

            publicCommands?.setBlock(targetNodeId, IMAGE_TYPE, {
              ...publicCommands?.getBlockComponentData(targetNodeId),
              image: undefined,
              tempData: url,
              loading: true,
              error: null,
            });

            trackBi?.start();
            const uploadFn = result.customUploadFn || handleFileUpload;

            if (!uploadFn) {
              logInvariant(Error('No upload function provided'));
              throw new Error('No upload function provided');
            }

            const uploadedFile = await upload(uploadFn, file);
            const { file_name, width, height } = (uploadedFile.data as ImageComponentData) || {};
            publicCommands?.setBlock(targetNodeId, IMAGE_TYPE, {
              ...publicCommands?.getBlockComponentData(targetNodeId),
              image: { src: { id: file_name }, width, height },
              tempData: null,
              loading: null,
              error: null,
            } satisfies PmImageNode['attrs']);

            URL.revokeObjectURL(url as string);
            trackBi?.success();
            return;
          } catch (error: any) {
            const componentData = publicCommands?.getBlockComponentData(targetNodeId);
            publicCommands?.setBlock(targetNodeId, IMAGE_TYPE, {
              ...componentData,
              error,
              loading: null,
            });

            trackBi?.error(error);
            services.uploadService.notifyError(error);
            return;
          }
        });
      });
    }
    case 'cancel': {
      services.modals.notifyExternalModalClosed({ focusReturnElement: referenceElement });
      return;
    }
    default: {
      console.error(unreachable(result));
      return;
    }
  }
};

const isPickMediaType = (
  data: ImageComponentData | PickMediaImageData
): data is PickMediaImageData => 'type' in data && data.type === 'image';

const getImageData = (data: ImageComponentData | PickMediaImageData) => {
  if (isPickMediaType(data)) {
    return {
      src: data.src,
      width: data.width,
      height: data.height,
    };
  }

  const { file_name, width, height } = data;
  return { src: { id: file_name }, width, height };
};
