import type { ImageData_CropShape } from './../ricos-schema/next-schema/index.js';

export type ShapeCropOption = {
  id: ImageData_CropShape;
  labelKey: string;
  dataHook: string;
};

type ShapeCropLabel = readonly [ImageData_CropShape, string];

export const getShapeCropDataHook = (shape: ImageData_CropShape) =>
  `shape-crop-dropdown-option-${shape.toLowerCase()}`;

const SHAPE_CROP_LABELS: readonly ShapeCropLabel[] = [
  ['CIRCLE', 'ImageShapeCrop_Circle'],
  ['OVAL', 'ImageShapeCrop_Ellipse'],
  ['TRIANGLE', 'ImageShapeCrop_Triangle'],
  ['STAR', 'ImageShapeCrop_Star'],
  ['HEART', 'ImageShapeCrop_Heart'],
  ['HEXAGON', 'ImageShapeCrop_Hexagon'],
  ['PENTAGON', 'ImageShapeCrop_Pentagon'],
  ['RHOMBUS', 'ImageShapeCrop_Rhombus'],
  ['FLUID', 'ImageShapeCrop_Fluid'],
  ['WINDOW', 'ImageShapeCrop_Window'],
];

export const SHAPE_CROP_OPTIONS: ShapeCropOption[] = SHAPE_CROP_LABELS.map(([id, labelKey]) => ({
  id,
  labelKey,
  dataHook: getShapeCropDataHook(id),
}));

export const SHAPE_CROP_IDS = SHAPE_CROP_OPTIONS.map(({ id }) => id);
