/* oxlint-disable @typescript-oxlint/no-unsafe-function-type */
import type { FC } from 'react';
import React, { useContext } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  UploadContext,
  useDevService,
} from './../../ricos-context/index.js';
import { useWixInstanceService } from './../../_shared/request-service-provider/wix-instance-context.js';
import { useEditorProps } from './../../_shared/some-editor-props-context.js';

import { IMAGE_EDITOR_MODAL_ID } from '../consts.js';
import { ImagePluginContext } from '../context.js';
import { handleImageUpload } from '../handle-image-upload.js';
import { setupImageEditor } from '../imageStudio/image-editor-logic.js';
import type { ImageEditorWixSettings, ImagePluginEditorConfig } from '../types.js';

interface Props {
  nodeId: string;
  src: string;
  config: ImagePluginEditorConfig;
}

const ROOT_ELEMENT_ID = 'imageEditor';

export const ImageEditorModal: FC<Props> = ({ nodeId, config, src }) => {
  const modalService = useContext(ModalServiceContext) || {};
  const { uploadService } = useContext(UploadContext) || {};
  const { getPublicCommands } = useContext(EditorContext);
  const imagePluginContext = useContext(ImagePluginContext);
  const devService = useDevService();
  const editorProps = useEditorProps();
  const wixInstance = useWixInstanceService();

  React.useEffect(() => {
    const onClose = () => {
      modalService.closeModal(IMAGE_EDITOR_MODAL_ID);
    };

    const onSave = (file: File) => {
      handleImageUpload({
        services: {
          uploadService: uploadService!,
          devService,
          editorProps,
          wixInstance,
          modals: modalService,
        },
        config,
        publicCommands: getPublicCommands(),
        nodeId,
        files: [file],
      });
      onClose();
    };

    const initializeImageEditor = async () => {
      const imageEditorSettings = await imagePluginContext?.getImageEditorSettings();

      setupImageEditor(
        imageEditorSettings ?? ({} as ImageEditorWixSettings),
        ROOT_ELEMENT_ID,
        src,
        onSave,
        onClose
      );
    };

    initializeImageEditor();
  }, [imagePluginContext]);

  // @ts-ignore
  // oxlint-disable-next-line react/no-unknown-property
  return <div id={ROOT_ELEMENT_ID} nofocus="true" />;
};
