import React from 'react';

import { useRequestService } from './../_shared/request-service-provider/request-service-provider.js';
import { useWixInstanceService } from './../_shared/request-service-provider/wix-instance-context.js';
import { useEditorProps } from './../_shared/some-editor-props-context.js';

import { fetchMediaToken } from './fetch-media-token.js';
import type { ImageEditorWixSettings } from './types.js';

type ImagePluginContextValue = {
  getImageEditorSettings: () => Promise<ImageEditorWixSettings | null>;
};

export const ImagePluginContext = React.createContext<ImagePluginContextValue | null>(null);

export const ImagePluginContextProvider = ({ children }: { children: React.ReactNode }) => {
  const [cachedSettings, setCachedSettings] = React.useState<ImageEditorWixSettings | null>(null);
  const wixInstance = useWixInstanceService();
  const { makeRequest } = useRequestService();
  const editorProps = useEditorProps();

  const getImageEditorSettings = React.useCallback(async () => {
    if (cachedSettings) {
      return cachedSettings;
    }

    const { metaSiteId } = wixInstance();
    if (!metaSiteId) {
      return null;
    }

    const token = await fetchMediaToken(makeRequest);
    const settings = token
      ? {
          initiator: editorProps.biSettings?.consumer || 'ricos-default',
          siteToken: token,
          metaSiteId,
          mediaRoot: 'photos',
        }
      : null;

    if (settings) {
      setCachedSettings(settings);
    }
    return settings;
  }, [cachedSettings, wixInstance]);

  return (
    <ImagePluginContext.Provider
      value={React.useMemo(() => ({ getImageEditorSettings }), [getImageEditorSettings])}
    >
      {children}
    </ImagePluginContext.Provider>
  );
};
