import type { PmConverters } from './../../pm-converters/collect.js';
import { TIPTAP_IMAGE_TYPE, generateId } from './../../ricos-content/index.js';
import type { Link as OldLink } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { CaptionNode, ImageNode, Link } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import { fromTiptapLinkConverter } from './../../_shared/link/link-converters.js';
import type { PmFigureNode, PmImageNode } from './../../_shared/pm-node-types.js';

import { captionToPlainText } from './caption-to-plain-text.js';

export const fromPmImageAnyState = (
  pmFigureNode: PmFigureNode,
  fromPmNode: PmConverters['fromPmNode']
): ImageNode | undefined => {
  const imageNode: PmImageNode | undefined = pmFigureNode.content?.find(
    ({ type }) => type === TIPTAP_IMAGE_TYPE
  ) as PmImageNode;

  if (!imageNode) {
    return undefined;
  }

  const { id, animation, ...imageData } = imageNode?.attrs || {};

  const captionNode = (fromPmNode(pmFigureNode)?.nodes?.[0] as CaptionNode) ?? [];
  const captionPlainText = captionToPlainText(pmFigureNode);

  const { spoiler, ...rest } = imageData.containerData || {};
  const containerData = {
    ...rest,
    ...(spoiler?.enabled ? { spoiler: { ...spoiler } } : {}),
  };

  const image = imageData.image ?? fallbackImage;

  return {
    type: Node_Type.IMAGE,
    id: id ?? generateId(),
    nodes: captionPlainText ? [captionNode] : [],
    imageData: {
      ...imageData,
      image,
      caption: captionPlainText,
      altText: imageData.altText || undefined,
      decorative: imageData.decorative || undefined,
      disableDownload: imageData.disableDownload || undefined,
      disableExpand: imageData.disableExpand || undefined,
      crop: imageData.crop || undefined,
      cropShape: imageData.cropShape || undefined,
      containerData: Object.keys(containerData).length ? containerData : undefined,
      styles: imageData.styles || undefined,
      link: imageData.link
        ? (fromTiptapLinkConverter(imageData.link as OldLink) as Link)
        : undefined,
      ...(animation ? { animation } : {}),
    },
  };
};

// This is an actual 1x1 transparent image
const fallbackImage = {
  src: {
    url: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR4nGNgYAAAAAMAASsJTYQAAAAASUVORK5CYII=',
  },
};
