import { definePmNodeConverter } from './../../pm-converters/types.js';
import { TIPTAP_FIGURE_TYPE, TIPTAP_IMAGE_TYPE, generateId } from './../../ricos-content/index.js';
import type {
  CaptionNode,
  Decoration,
  ImageNode,
  Link,
  Node,
} from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import { fromTiptapLinkConverter } from './../../_shared/link/link-converters.js';

import { captionToPlainText } from './caption-to-plain-text.js';

export const imageConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.IMAGE],
    convert: (node, visit) => {
      const { containerData, caption: imageCaption, ...imageData } = node.imageData;

      const fallbackCaption = {
        id: generateId(),
        type: Node_Type.CAPTION,
        nodes:
          typeof imageCaption === 'string' && imageCaption.length
            ? [
                {
                  type: Node_Type.TEXT,
                  id: '',
                  nodes: [],
                  textData: {
                    text: imageCaption,
                    decorations: [] as Decoration[],
                  },
                },
              ]
            : [],
      } as unknown as Node;

      const fallBackNodeWithCaption = { ...node, nodes: [fallbackCaption] } as ImageNode;

      return {
        type: TIPTAP_FIGURE_TYPE,
        attrs: {
          id: generateId(),
        },
        content: [
          {
            type: TIPTAP_IMAGE_TYPE,
            attrs: {
              ...imageData,
              containerData,
              id: node.id,
              disableDownload: !!imageData.disableDownload,
              disableExpand: !!imageData.disableExpand,
              decorative: !!imageData.decorative,
            },
          },
          ...(visit?.((node.nodes?.length ?? 0) > 0 ? node : fallBackNodeWithCaption) ?? []),
        ],
      };
    },
  },
  fromPm: {
    types: [TIPTAP_FIGURE_TYPE, TIPTAP_IMAGE_TYPE],
    convert: (node, visit) => {
      if (node.type === TIPTAP_IMAGE_TYPE) {
        return undefined;
      }

      const imageNode = node.content?.find(({ type }) => type === TIPTAP_IMAGE_TYPE);

      if (!imageNode) {
        return undefined;
      }

      const { id, loading, error, animation, ...imageData } = imageNode?.attrs || {};

      if (loading || error) {
        return undefined;
      }

      const [captionNode] = visit?.(node) ?? [];
      const captionPlainText = captionToPlainText(node);

      const { spoiler, ...rest } = imageData.containerData || {};
      const containerData = {
        ...rest,
        ...(spoiler?.enabled ? { spoiler: { ...spoiler } } : {}),
      };

      return {
        type: Node_Type.IMAGE,
        id: id ?? generateId(),
        nodes: captionPlainText ? [captionNode as CaptionNode] : [],
        imageData: {
          ...imageData,
          caption: captionPlainText,
          altText: imageData.altText || undefined,
          decorative: imageData.decorative || undefined,
          disableDownload: imageData.disableDownload || undefined,
          disableExpand: imageData.disableExpand || undefined,
          crop: imageData.crop || undefined,
          cropShape: imageData.cropShape || undefined,
          containerData: Object.keys(containerData).length ? containerData : undefined,
          link: fromTiptapLinkConverter(imageData.link) as Link,
          ...(animation ? { animation } : {}),
        },
      } as unknown as ImageNode;
    },
  },
});
