import type { ImageData_Crop } from './../../ricos-schema/next-schema/index.js';
import { minMax } from './../../tiptap/index.js';

/** A rectangle in pixel coordinates; compared rects must share the same coordinate space. */
export type Rect = { x: number; y: number; width: number; height: number };

export type Direction =
  | 'left'
  | 'right'
  | 'top'
  | 'bottom'
  | 'topLeft'
  | 'topRight'
  | 'bottomLeft'
  | 'bottomRight';

/** Smallest on-screen size (px) the overlay crop frame may shrink to (keeps handles grabbable). */
export const MIN_FRAME_SIZE = 24;

const CROP_DECIMAL_PLACES = 6;

const roundCropValue = (value: number) => Number(value.toFixed(CROP_DECIMAL_PLACES));

const getDirectionEdges = (direction: Direction) => ({
  isLeft: direction === 'left' || direction.endsWith('Left'),
  isRight: direction === 'right' || direction.endsWith('Right'),
  isTop: direction.startsWith('top'),
  isBottom: direction.startsWith('bottom'),
});

export const roundCrop = ({ x, y, width, height }: Required<ImageData_Crop>): ImageData_Crop => {
  const roundedWidth = minMax(roundCropValue(width), 0, 1);
  const roundedHeight = minMax(roundCropValue(height), 0, 1);

  return {
    x: minMax(roundCropValue(x), 0, 1 - roundedWidth),
    y: minMax(roundCropValue(y), 0, 1 - roundedHeight),
    width: roundedWidth,
    height: roundedHeight,
  };
};

/** Resize the crop frame from one handle; the opposite edge stays anchored, clamped to `bounds`. */
export const resizeFrame = (
  frame: Rect,
  direction: Direction,
  deltaX: number,
  deltaY: number,
  bounds: Rect
): Rect => {
  let { x, y, width, height } = frame;
  const right = x + width;
  const bottom = y + height;

  const { isLeft, isRight, isTop, isBottom } = getDirectionEdges(direction);

  if (isLeft) {
    const newX = minMax(x + deltaX, bounds.x, right - MIN_FRAME_SIZE);
    width = right - newX;
    x = newX;
  } else if (isRight) {
    width = minMax(width + deltaX, MIN_FRAME_SIZE, bounds.x + bounds.width - x);
  }

  if (isTop) {
    const newY = minMax(y + deltaY, bounds.y, bottom - MIN_FRAME_SIZE);
    height = bottom - newY;
    y = newY;
  } else if (isBottom) {
    height = minMax(height + deltaY, MIN_FRAME_SIZE, bounds.y + bounds.height - y);
  }

  return { x, y, width, height };
};

const getMinimumAspectWidth = (aspectRatio: number) => MIN_FRAME_SIZE * Math.max(1, aspectRatio);

const getAspectFrameMaxWidth = (
  bounds: Rect,
  aspectRatio: number,
  maxWidth: number,
  maxHeight: number
) => Math.max(0, Math.min(bounds.width, maxWidth, maxHeight * aspectRatio));

/** Fit a crop frame to a target aspect ratio, preserving center and area whenever bounds allow. */
export const fitFrameToAspectRatio = (frame: Rect, bounds: Rect, aspectRatio: number): Rect => {
  if (!Number.isFinite(aspectRatio) || aspectRatio <= 0) {
    return frame;
  }

  const centerX = minMax(frame.x + frame.width / 2, bounds.x, bounds.x + bounds.width);
  const centerY = minMax(frame.y + frame.height / 2, bounds.y, bounds.y + bounds.height);
  const maxCenteredWidth = 2 * Math.min(centerX - bounds.x, bounds.x + bounds.width - centerX);
  const maxCenteredHeight = 2 * Math.min(centerY - bounds.y, bounds.y + bounds.height - centerY);
  const maxWidth = getAspectFrameMaxWidth(bounds, aspectRatio, maxCenteredWidth, maxCenteredHeight);
  const minimumWidth = Math.min(maxWidth, getMinimumAspectWidth(aspectRatio));
  const preferredWidth = Math.sqrt(frame.width * frame.height * aspectRatio);
  const width = minMax(preferredWidth, minimumWidth, maxWidth);
  const height = width / aspectRatio;
  const x = minMax(centerX - width / 2, bounds.x, bounds.x + bounds.width - width);
  const y = minMax(centerY - height / 2, bounds.y, bounds.y + bounds.height - height);

  return { x, y, width, height };
};

/** Resize a crop frame from one handle while preserving an arbitrary aspect ratio. */
export const resizeAspectFrame = (
  frame: Rect,
  direction: Direction,
  deltaX: number,
  deltaY: number,
  bounds: Rect,
  aspectRatio: number
): Rect => {
  if (!Number.isFinite(aspectRatio) || aspectRatio <= 0) {
    return resizeFrame(frame, direction, deltaX, deltaY, bounds);
  }

  const right = frame.x + frame.width;
  const bottom = frame.y + frame.height;
  const centerX = frame.x + frame.width / 2;
  const centerY = frame.y + frame.height / 2;

  const { isLeft, isRight, isTop, isBottom } = getDirectionEdges(direction);

  const horizontalDelta = isLeft ? -deltaX : isRight ? deltaX : 0;
  const verticalDelta = isTop ? -deltaY : isBottom ? deltaY : 0;
  const widthDelta =
    Math.abs(horizontalDelta) > Math.abs(verticalDelta * aspectRatio)
      ? horizontalDelta
      : verticalDelta * aspectRatio;

  const maxWidth = isLeft
    ? right - bounds.x
    : isRight
      ? bounds.x + bounds.width - frame.x
      : 2 * Math.min(centerX - bounds.x, bounds.x + bounds.width - centerX);
  const maxHeight = isTop
    ? bottom - bounds.y
    : isBottom
      ? bounds.y + bounds.height - frame.y
      : 2 * Math.min(centerY - bounds.y, bounds.y + bounds.height - centerY);
  const maxAspectWidth = getAspectFrameMaxWidth(bounds, aspectRatio, maxWidth, maxHeight);
  const minimumWidth = Math.min(maxAspectWidth, getMinimumAspectWidth(aspectRatio));
  const width = minMax(frame.width + widthDelta, minimumWidth, maxAspectWidth);
  const height = width / aspectRatio;

  const x = isLeft ? right - width : isRight ? frame.x : centerX - width / 2;
  const y = isTop ? bottom - height : isBottom ? frame.y : centerY - height / 2;

  return { x, y, width, height };
};

/** Pan the image, keeping it covering the frame (never reveal a blank edge). */
export const moveImage = (image: Rect, deltaX: number, deltaY: number, frame: Rect): Rect => ({
  ...image,
  x: minMax(image.x + deltaX, frame.x + frame.width - image.width, frame.x),
  y: minMax(image.y + deltaY, frame.y + frame.height - image.height, frame.y),
});

/** Zoom the image about a focal point, never smaller than (and always covering) the frame. */
export const zoomImage = (
  image: Rect,
  frame: Rect,
  factor: number,
  focalX: number,
  focalY: number
): Rect => {
  const minFactor = Math.max(frame.width / image.width, frame.height / image.height);
  const f = Math.max(minFactor, factor);
  const width = image.width * f;
  const height = image.height * f;
  const x = minMax(focalX - (focalX - image.x) * f, frame.x + frame.width - width, frame.x);
  const y = minMax(focalY - (focalY - image.y) * f, frame.y + frame.height - height, frame.y);
  return { x, y, width, height };
};

/** Express the frame as crop fractions relative to the full-image rectangle. */
export const rectsToCrop = (image: Rect, frame: Rect): ImageData_Crop =>
  roundCrop({
    x: (frame.x - image.x) / image.width,
    y: (frame.y - image.y) / image.height,
    width: frame.width / image.width,
    height: frame.height / image.height,
  });
