import React, { useCallback, useContext, useRef, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { getElementScale } from './../../_shared/get-element-scale.js';

import styles from './corner-radius-handles-scss.js';

const MAX_RADIUS = 300;
const MIN_RADIUS = 0;
const HANDLE_SIZE = 10;
const HANDLE_INSET = 16;
const CENTER_GAP = 8;
const SHIFT_SNAP_STEP = 20;

type Corner = 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight';

type CornerRadiusHandlesProps = {
  containerRef: React.RefObject<HTMLElement | null>;
  currentRadius: number;
  onRadiusChange: (radius: number) => void;
  onDraggingChange?: (isDragging: boolean) => void;
};

const clampRadius = (value: number, upperBound: number): number =>
  Math.round(Math.max(MIN_RADIUS, Math.min(upperBound, value)));

const snapToStep = (value: number, step: number): number => Math.round(value / step) * step;

export const CornerRadiusHandles: React.FC<CornerRadiusHandlesProps> = ({
  containerRef,
  currentRadius,
  onRadiusChange,
  onDraggingChange,
}) => {
  const { t } = useContext(RicosContext) ?? {
    t: (key: string, _opts?: { value?: number }) =>
      _opts?.value !== undefined ? `Radius ${_opts.value}` : key,
  };
  const [draggingCorner, setDraggingCorner] = useState<Corner | null>(null);
  const dragCornerRef = useRef<Corner | null>(null);

  const computeRadiusFromPoint = useCallback(
    (clientX: number, clientY: number, corner: Corner): number => {
      const el = containerRef.current;
      if (!el) {
        return currentRadius;
      }

      const rect = el.getBoundingClientRect();
      const { scaleX, scaleY } = getElementScale(el);
      const x = (clientX - rect.left) / scaleX;
      const y = (clientY - rect.top) / scaleY;
      const width = rect.width / scaleX;
      const height = rect.height / scaleY;
      const halfHandle = HANDLE_SIZE / 2;
      const originOffset = HANDLE_INSET + halfHandle;
      const maxPhysical = Math.max(
        0,
        Math.min(width / 2 - originOffset - CENTER_GAP, height / 2 - originOffset - CENTER_GAP)
      );

      if (maxPhysical <= 0) {
        return currentRadius;
      }

      let physicalRadius: number;
      switch (corner) {
        case 'topLeft':
          physicalRadius = Math.max(0, Math.min(x - originOffset, y - originOffset));
          break;
        case 'topRight':
          physicalRadius = Math.max(0, Math.min(width - originOffset - x, y - originOffset));
          break;
        case 'bottomLeft':
          physicalRadius = Math.max(0, Math.min(x - originOffset, height - originOffset - y));
          break;
        case 'bottomRight':
          physicalRadius = Math.max(
            0,
            Math.min(width - originOffset - x, height - originOffset - y)
          );
          break;
        default:
          return currentRadius;
      }

      const normalized = Math.min(1, physicalRadius / maxPhysical);
      return clampRadius(Math.round(normalized * MAX_RADIUS), MAX_RADIUS);
    },
    [containerRef, currentRadius]
  );

  const handlePointerDown = useCallback(
    (event: React.PointerEvent, corner: Corner) => {
      event.preventDefault();
      event.stopPropagation();
      dragCornerRef.current = corner;
      setDraggingCorner(corner);
      onDraggingChange?.(true);
      (event.target as HTMLElement).setPointerCapture(event.pointerId);
    },
    [onDraggingChange]
  );

  const handlePointerMove = useCallback(
    (event: React.PointerEvent, corner: Corner) => {
      if (dragCornerRef.current === null) {
        return;
      }
      event.preventDefault();
      let newRadius = computeRadiusFromPoint(event.clientX, event.clientY, corner);
      if (event.shiftKey) {
        newRadius = snapToStep(newRadius, SHIFT_SNAP_STEP);
      }
      onRadiusChange(newRadius);
    },
    [computeRadiusFromPoint, onRadiusChange]
  );

  const handlePointerUp = useCallback(
    (event: React.PointerEvent) => {
      dragCornerRef.current = null;
      setDraggingCorner(null);
      onDraggingChange?.(false);
      (event.target as HTMLElement).releasePointerCapture(event.pointerId);
    },
    [onDraggingChange]
  );

  const rect = containerRef.current?.getBoundingClientRect();
  const width = rect?.width ?? 0;
  const height = rect?.height ?? 0;
  const halfHandle = HANDLE_SIZE / 2;
  const maxPhysical = Math.max(
    0,
    Math.min(
      width / 2 - HANDLE_INSET - halfHandle - CENTER_GAP,
      height / 2 - HANDLE_INSET - halfHandle - CENTER_GAP
    )
  );

  const radiusClamped = Math.min(Math.max(currentRadius, MIN_RADIUS), MAX_RADIUS);
  const effectiveRadius = maxPhysical > 0 ? (radiusClamped / MAX_RADIUS) * maxPhysical : 0;

  const LABEL_OFFSET_HORIZONTAL = 6;
  const LABEL_OFFSET_VERTICAL = 4;

  const handlePositions: Record<Corner, React.CSSProperties> = {
    topLeft: {
      left: HANDLE_INSET + effectiveRadius,
      top: HANDLE_INSET + effectiveRadius,
    },
    topRight: {
      right: HANDLE_INSET + effectiveRadius,
      top: HANDLE_INSET + effectiveRadius,
    },
    bottomLeft: {
      left: HANDLE_INSET + effectiveRadius,
      bottom: HANDLE_INSET + effectiveRadius,
    },
    bottomRight: {
      right: HANDLE_INSET + effectiveRadius,
      bottom: HANDLE_INSET + effectiveRadius,
    },
  };

  const radiusLabelPosition: Record<Corner, React.CSSProperties> = {
    topLeft: {
      left: HANDLE_INSET + effectiveRadius + LABEL_OFFSET_HORIZONTAL,
      top: HANDLE_INSET + effectiveRadius - LABEL_OFFSET_VERTICAL,
      transform: 'translateY(-100%)',
    },
    topRight: {
      right: HANDLE_INSET + effectiveRadius + LABEL_OFFSET_HORIZONTAL,
      top: HANDLE_INSET + effectiveRadius - LABEL_OFFSET_VERTICAL,
      transform: 'translateY(-100%)',
    },
    bottomLeft: {
      left: HANDLE_INSET + effectiveRadius + LABEL_OFFSET_HORIZONTAL,
      bottom: HANDLE_INSET + effectiveRadius + HANDLE_SIZE + LABEL_OFFSET_VERTICAL,
    },
    bottomRight: {
      right: HANDLE_INSET + effectiveRadius + LABEL_OFFSET_HORIZONTAL,
      bottom: HANDLE_INSET + effectiveRadius + HANDLE_SIZE + LABEL_OFFSET_VERTICAL,
    },
  };

  return (
    <div className={styles.overlay} aria-hidden>
      {draggingCorner !== null && (
        <div
          className={styles.radiusLabel}
          style={radiusLabelPosition[draggingCorner]}
          data-hook="image-corner-radius-label"
        >
          {t('ImagePlugin_Corner_Radius_Label', { value: currentRadius })}
        </div>
      )}
      {(['topLeft', 'topRight', 'bottomLeft', 'bottomRight'] as const).map(corner => (
        <div
          key={corner}
          className={styles.handle}
          data-corner={corner}
          data-hook="image-corner-radius-handle"
          style={handlePositions[corner]}
          onPointerDown={e => handlePointerDown(e, corner)}
          onPointerMove={e => handlePointerMove(e, corner)}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          role="slider"
          aria-valuenow={currentRadius}
          aria-valuemin={MIN_RADIUS}
          aria-valuemax={MAX_RADIUS}
        >
          <span className={styles.handleDot} />
        </div>
      ))}
    </div>
  );
};
