import type { ImageProps } from './../bundled-dependencies/wix-image.js';
import type { EditorPluginConfig, ViewerPluginConfig } from './../ricos-types/index.js';

export const IMAGE_TYPE = 'wix-draft-plugin-image';

export type ImageEditorWixSettings = {
  initiator: string;
  siteToken: string;
  metaSiteId: string;
  mediaRoot: string;
};

export interface ImagePluginEditorConfig extends EditorPluginConfig {
  type: 'image';
  /**
   * @default false
   * @deprecated Nobody uses this
   * This is initial value of 'disableDownload' field in RicosDocument's ImageData for inserted images
   */
  disableDownload?: boolean;
  /**
   * @default false
   * This is initial value of 'disableExpand' field in RicosDocument's ImageData for inserted images
   */
  disableExpand?: boolean;
  /**
   * @deprecated has no effect
   */
  createGalleryForMultipleImages?: boolean;
  /**
   * @default false
   * If set to true it will enable the image editor
   */
  imageEditor?: boolean;

  accept?: string;

  multi?: boolean;

  colors?: {
    color1?: string; // used for default textColor
    color2?: string;
    color3?: string;
    color4?: string;
    color5?: string;
    color6?: string;
    color7?: string;
    color8?: string;
    color9?: string;
    color10?: string;
  };
  /** @deprecated Use colorManager prop instead */
  onBorderColorAdded?: (color: string) => string[];
  /** @deprecated Use colorManager prop instead */
  getBorderColors?: () => string[];

  /**
   * @deprecated has no effect
   */
  consumer?: string;
  /**
   * @deprecated has no effect in editor
   */
  disableTransition?: boolean;
}

export interface ImagePluginViewerConfig extends ViewerPluginConfig {
  onExpand?: (blockkey: string) => unknown;
  /**
   * @default false
   * If set to true it will always remove the expand button from the image despite nodes data
   */
  disableExpand?: boolean;
  /**
   * @default false
   * @deprecated No usecases was found for it, currently doesn't work
   */
  disableDownload?: boolean;
  disableTransition?: boolean;
  imageProps?: ((src: Record<string, unknown>) => HTMLImageElement) | HTMLImageElement;
  encoding?: ImageProps['encoding'];

  colors?: {
    color1?: string; // used for default textColor
    color2?: string;
    color3?: string;
    color4?: string;
    color5?: string;
    color6?: string;
    color7?: string;
    color8?: string;
    color9?: string;
    color10?: string;
  };
}

export type ExtendedBlob = Blob & {
  lastModified: number;
  name: string;
  webkitRelativePath: string;
};
