import type { PmNodeJson } from './../../pm-converters/types.js';
import { TIPTAP_CAPTION_TYPE } from './../../ricos-content/index.js';

export const captionToPlainText = (node: PmNodeJson): string | undefined => {
  const captionNode = node.content?.find(({ type }) => type === TIPTAP_CAPTION_TYPE) as PmNodeJson;

  return (
    captionNode?.content?.reduce((acc, { text }) => (text !== undefined ? acc + text : acc), '') ||
    undefined
  );
};
