import type { ImageData_CropShape } from './../../ricos-schema/next-schema/index.js';

import { IMAGE_CROP_OVERLAY } from '../data-hooks.js';
import { SHAPE_CROP_IDS } from '../shape-crop-shapes.js';

export const getShapeCrop = (attrs: Record<string, unknown>): ImageData_CropShape | null =>
  isShapeCrop(attrs.cropShape) ? attrs.cropShape : null;

export const isShapeCrop = (value: unknown): value is ImageData_CropShape =>
  typeof value === 'string' && SHAPE_CROP_IDS.includes(value as ImageData_CropShape);

export const isShapeCropModalInteractionTarget = (
  target: EventTarget | null,
  referenceElement?: HTMLElement
): boolean =>
  target instanceof Node &&
  (Boolean(referenceElement?.contains(target)) ||
    (target instanceof Element &&
      Boolean(
        target.closest(`[data-hook='${IMAGE_CROP_OVERLAY}'], [data-hook^='figure-'][data-cropping]`)
      )));
