import type { RequestService } from './../_shared/request-service-provider/request-service-provider.js';

const BASE_URL = '/_serverless/ricos-media-services/media-token';

export const fetchMediaToken = async (makeRequest: RequestService['makeRequest']) => {
  const response = await makeRequest(BASE_URL);

  if (!response.ok) {
    console.error('Failed to get media token');
    return null;
  }

  const token = (await response.text()).replace(/^"+|"+$/g, '');

  if (token && token.startsWith('JWS.')) {
    return token;
  }

  return null;
};
