import { Check, X } from '@wix/wix-ui-icons-common/lazy';
import React, {
  useCallback,
  useContext,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import ReactDOM from 'react-dom';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { EDITOR_ROOT } from './../../ricos-editor/data-hooks.js';
import type { ImageData_Crop, ImageData_CropShape } from './../../ricos-schema/next-schema/index.js';
import { normalize } from './../../_shared/media/image-crop.js';

import {
  IMAGE_CROP_APPLY,
  IMAGE_CROP_CANCEL,
  IMAGE_CROP_OVERLAY,
  IMAGE_VIEWER_SELECTOR,
} from '../data-hooks.js';
import { getShapeCropMaskDataUri } from '../shape-crop-mask-data.js';
import { CropFrame } from './crop-frame.js';
import {
  fitFrameToAspectRatio,
  moveImage,
  rectsToCrop,
  resizeAspectFrame,
  resizeFrame,
  zoomImage,
  type Direction,
  type Rect,
} from './crop-geometry.js';
import styles from './crop-overlay-scss.js';

// Wheel/pinch zoom sensitivity (trackpad pinch arrives as a ctrl+wheel event).
const ZOOM_SPEED = 0.0015;

export type CropApply = {
  crop: ImageData_Crop;
  /** Omitted for shape crops, which must preserve the image node's displayed width. */
  widthPx?: number;
};
export type CropOverlayHandle = { apply: () => boolean; cancel: () => void };

type CropOverlayProps = {
  actionsRef: React.RefObject<CropOverlayHandle | null>;
  containerRef: React.RefObject<HTMLElement | null>;
  imageSrc: string;
  crop: ImageData_Crop | null;
  cropShape?: ImageData_CropShape | null;
  aspectRatio?: number | null;
  onApply: (next: CropApply) => void;
  onCancel: () => void;
};

type DragState =
  | { kind: 'handle'; direction: Direction; startX: number; startY: number; startFrame: Rect }
  | { kind: 'move'; startX: number; startY: number; startImage: Rect };

type Geometry = { full: Rect; frame: Rect };
type Point = { x: number; y: number };
type ElementTransform = { rect: DOMRect; scaleX: number; scaleY: number };

const getElementTransform = (element: HTMLElement): ElementTransform => {
  const rect = element.getBoundingClientRect();
  return {
    rect,
    scaleX: element.offsetWidth > 0 ? rect.width / element.offsetWidth : 1,
    scaleY: element.offsetHeight > 0 ? rect.height / element.offsetHeight : 1,
  };
};

const toLocalPoint = (element: HTMLElement, clientX: number, clientY: number): Point => {
  const { rect, scaleX, scaleY } = getElementTransform(element);
  return {
    x: (clientX - rect.left) / scaleX,
    y: (clientY - rect.top) / scaleY,
  };
};

const findNearestClippingAncestor = (element: HTMLElement | null): HTMLElement | null => {
  if (!element) {
    return null;
  }

  const { overflow, overflowX, overflowY } = window.getComputedStyle(element);
  return [overflow, overflowX, overflowY].some(value => value === 'hidden' || value === 'clip')
    ? element
    : findNearestClippingAncestor(element.parentElement);
};

const resolveOverlayContainer = (imageContainer: HTMLElement): HTMLElement => {
  const editorRoot = imageContainer.closest<HTMLElement>(`[data-hook~="${EDITOR_ROOT}"]`);
  const clippingAncestor = findNearestClippingAncestor(editorRoot?.parentElement ?? null);

  return clippingAncestor?.parentElement ?? editorRoot ?? imageContainer;
};

/**
 * In-place crop UI: reveals the full image (faded) around a movable/resizable frame in a layer at
 * the nearest layer outside the editor's clipping boundary. It remains attached to the document
 * canvas while allowing the crop preview to extend beyond the document.
 */
export const CropOverlay: React.FC<CropOverlayProps> = ({
  actionsRef,
  containerRef,
  imageSrc,
  crop,
  cropShape,
  aspectRatio = null,
  onApply,
  onCancel,
}) => {
  const { t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const dragRef = useRef<DragState | null>(null);
  const geometryRef = useRef<Geometry | null>(null);
  const overlayContainerRef = useRef<HTMLElement | null>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  const [geometry, setGeometry] = useState<Geometry | null>(null);
  const [activeDirection, setActiveDirection] = useState<Direction | null>(null);
  const overlayReady = geometry !== null;
  const normalizedAspectRatio =
    typeof aspectRatio === 'number' && Number.isFinite(aspectRatio) && aspectRatio > 0
      ? aspectRatio
      : null;
  const aspectRatioRef = useRef<number | null>(normalizedAspectRatio);

  useLayoutEffect(() => {
    aspectRatioRef.current = normalizedAspectRatio;
  }, [normalizedAspectRatio]);

  const apply = useCallback((next: Geometry) => {
    geometryRef.current = next;
    setGeometry(next);
  }, []);

  // Derive the full-image rect and initial frame from the visible image box. Retry until the
  // box is laid out (dimensions may still be resolving), else the overlay would stay empty.
  useLayoutEffect(() => {
    let rafId = 0;
    let positionedContainer: HTMLElement | null = null;
    const measure = () => {
      const imageContainer = containerRef.current;
      const imageBox = imageContainer?.querySelector<HTMLElement>(IMAGE_VIEWER_SELECTOR);
      const boxRect = imageBox?.getBoundingClientRect();
      if (!imageContainer || !boxRect || boxRect.width === 0 || boxRect.height === 0) {
        rafId = requestAnimationFrame(measure);
        return;
      }

      const overlayContainer = resolveOverlayContainer(imageContainer);
      if (window.getComputedStyle(overlayContainer).position === 'static') {
        overlayContainer.style.position = 'relative';
        positionedContainer = overlayContainer;
      }
      overlayContainerRef.current = overlayContainer;
      const { rect: overlayRect, scaleX, scaleY } = getElementTransform(overlayContainer);
      const boxX = (boxRect.left - overlayRect.left) / scaleX;
      const boxY = (boxRect.top - overlayRect.top) / scaleY;
      const boxWidth = boxRect.width / scaleX;
      const boxHeight = boxRect.height / scaleY;

      const c = normalize(crop);
      const baseWidth = boxWidth / c.width;
      const baseHeight = boxHeight / c.height;
      const full: Rect = {
        x: boxX - c.x * baseWidth,
        y: boxY - c.y * baseHeight,
        width: baseWidth,
        height: baseHeight,
      };
      const visibleFrame: Rect = {
        x: boxX,
        y: boxY,
        width: boxWidth,
        height: boxHeight,
      };
      const frame = aspectRatioRef.current
        ? fitFrameToAspectRatio(visibleFrame, full, aspectRatioRef.current)
        : visibleFrame;
      apply({ full, frame });
    };
    measure();
    return () => {
      cancelAnimationFrame(rafId);
      positionedContainer?.style.removeProperty('position');
    };
  }, [containerRef, crop, apply]);

  useEffect(() => {
    const geo = geometryRef.current;

    if (!geo || !normalizedAspectRatio) {
      return;
    }

    apply({
      full: geo.full,
      frame: fitFrameToAspectRatio(geo.frame, geo.full, normalizedAspectRatio),
    });
  }, [normalizedAspectRatio, apply]);

  const onPointerMove = useCallback(
    (event: PointerEvent) => {
      const drag = dragRef.current;
      const geo = geometryRef.current;
      const overlayContainer = overlayContainerRef.current;
      if (!drag || !geo || !overlayContainer) {
        return;
      }
      const pointer = toLocalPoint(overlayContainer, event.clientX, event.clientY);
      const deltaX = pointer.x - drag.startX;
      const deltaY = pointer.y - drag.startY;
      if (drag.kind === 'move') {
        apply({ full: moveImage(drag.startImage, deltaX, deltaY, geo.frame), frame: geo.frame });
      } else {
        const frame = normalizedAspectRatio
          ? resizeAspectFrame(
              drag.startFrame,
              drag.direction,
              deltaX,
              deltaY,
              geo.full,
              normalizedAspectRatio
            )
          : resizeFrame(drag.startFrame, drag.direction, deltaX, deltaY, geo.full);
        apply({ full: geo.full, frame });
      }
    },
    [normalizedAspectRatio, apply]
  );

  const endDrag = useCallback(() => {
    dragRef.current = null;
    setActiveDirection(null);
    window.removeEventListener('pointermove', onPointerMove);
    window.removeEventListener('pointerup', endDrag);
  }, [onPointerMove]);

  const beginDrag = useCallback(
    (drag: DragState, event: React.PointerEvent) => {
      dragRef.current = drag;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      window.addEventListener('pointermove', onPointerMove);
      window.addEventListener('pointerup', endDrag);
    },
    [onPointerMove, endDrag]
  );

  useEffect(() => endDrag, [endDrag]);

  // Wheel / trackpad-pinch zoom. Native non-passive listener so we can preventDefault page zoom.
  useEffect(() => {
    const el = overlayRef.current;
    if (!el) {
      return;
    }
    const onWheel = (event: WheelEvent) => {
      const geo = geometryRef.current;
      if (!geo) {
        return;
      }

      const overlayContainer = overlayContainerRef.current;
      if (!overlayContainer) {
        return;
      }

      const focalPoint = toLocalPoint(overlayContainer, event.clientX, event.clientY);
      const isInsideFrame =
        focalPoint.x >= geo.frame.x &&
        focalPoint.x <= geo.frame.x + geo.frame.width &&
        focalPoint.y >= geo.frame.y &&
        focalPoint.y <= geo.frame.y + geo.frame.height;

      if (!isInsideFrame) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      const factor = Math.exp(-event.deltaY * ZOOM_SPEED);
      apply({
        full: zoomImage(geo.full, geo.frame, factor, focalPoint.x, focalPoint.y),
        frame: geo.frame,
      });
    };
    el.addEventListener('wheel', onWheel, { passive: false });
    return () => el.removeEventListener('wheel', onWheel);
  }, [overlayReady, apply]);

  // Escape cancels crop mode.
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        onCancel();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [onCancel]);

  const onHandlePointerDown = useCallback(
    (direction: Direction, event: React.PointerEvent) => {
      event.preventDefault();
      event.stopPropagation();
      const overlayContainer = overlayContainerRef.current;
      if (!geometryRef.current || !overlayContainer) {
        return;
      }
      const pointer = toLocalPoint(overlayContainer, event.clientX, event.clientY);
      setActiveDirection(direction);
      beginDrag(
        {
          kind: 'handle',
          direction,
          startX: pointer.x,
          startY: pointer.y,
          startFrame: geometryRef.current.frame,
        },
        event
      );
    },
    [beginDrag]
  );

  const onMovePointerDown = useCallback(
    (event: React.PointerEvent) => {
      event.preventDefault();
      event.stopPropagation();
      const overlayContainer = overlayContainerRef.current;
      if (!geometryRef.current || !overlayContainer) {
        return;
      }
      const pointer = toLocalPoint(overlayContainer, event.clientX, event.clientY);
      beginDrag(
        {
          kind: 'move',
          startX: pointer.x,
          startY: pointer.y,
          startImage: geometryRef.current.full,
        },
        event
      );
    },
    [beginDrag]
  );

  const handleApply = useCallback(() => {
    const geo = geometryRef.current;
    if (!geo) {
      return false;
    }

    onApply({
      crop: rectsToCrop(geo.full, geo.frame),
      ...(cropShape ? {} : { widthPx: Math.round(geo.frame.width) }),
    });
    return true;
  }, [cropShape, onApply]);

  useImperativeHandle(actionsRef, () => ({ apply: handleApply, cancel: onCancel }), [
    handleApply,
    onCancel,
  ]);

  const overlayContainer = overlayContainerRef.current;

  if (!geometry || !overlayContainer) {
    return null;
  }

  const { full, frame } = geometry;
  const shapePreviewMask = getShapeCropMaskDataUri(cropShape);
  // Frame relative to the full-image layer (both are in overlay-container coordinates).
  const frameInLayer: Rect = {
    x: frame.x - full.x,
    y: frame.y - full.y,
    width: frame.width,
    height: frame.height,
  };

  return ReactDOM.createPortal(
    <div
      className={styles.overlay}
      data-hook={IMAGE_CROP_OVERLAY}
      ref={overlayRef}
      style={{ zIndex: zIndexService.getZIndex('POPUP') }}
    >
      {/* Clipped layer: the full image + the dark mask (its hole is the crop window). */}
      <div
        className={styles.fullLayer}
        style={{ left: full.x, top: full.y, width: full.width, height: full.height }}
      >
        <img className={styles.fullImage} src={imageSrc} alt="" draggable={false} />
        <div
          className={styles.mask}
          style={{
            left: frameInLayer.x,
            top: frameInLayer.y,
            width: frameInLayer.width,
            height: frameInLayer.height,
          }}
        />
        {shapePreviewMask && (
          <div
            className={styles.shapePreview}
            style={{
              left: frameInLayer.x,
              top: frameInLayer.y,
              width: frameInLayer.width,
              height: frameInLayer.height,
              WebkitMaskImage: `linear-gradient(#fff 0 0), url("${shapePreviewMask}")`,
              maskImage: `linear-gradient(#fff 0 0), url("${shapePreviewMask}")`,
              WebkitMaskRepeat: 'no-repeat, no-repeat',
              maskRepeat: 'no-repeat, no-repeat',
              WebkitMaskPosition: 'center, center',
              maskPosition: 'center, center',
              WebkitMaskSize: '100% 100%, contain',
              maskSize: '100% 100%, contain',
              WebkitMaskComposite: 'xor',
              maskComposite: 'exclude',
            }}
            aria-hidden
          />
        )}
      </div>
      {/* Outside the clip so handles are never cut off. */}
      <CropFrame
        frame={frame}
        activeDirection={activeDirection}
        locked={Boolean(normalizedAspectRatio)}
        onHandlePointerDown={onHandlePointerDown}
        onMovePointerDown={onMovePointerDown}
      />

      <div
        className={styles.actions}
        style={{ left: frame.x + frame.width, top: frame.y + frame.height }}
      >
        <button
          type="button"
          className={styles.cancelButton}
          onClick={onCancel}
          data-hook={IMAGE_CROP_CANCEL}
          aria-label={t('ImageCrop_Cancel')}
        >
          <X />
        </button>
        <button
          type="button"
          className={styles.applyButton}
          onClick={handleApply}
          data-hook={IMAGE_CROP_APPLY}
          aria-label={t('ImageCrop_Apply')}
        >
          <Check />
        </button>
      </div>
    </div>,
    overlayContainer
  );
};
