import React, { useCallback, useRef, useState } from 'react';

import {
  PluginContainerData_Alignment,
  type ImageData_Crop,
} from './../../ricos-schema/next-schema/index.js';
import { getElementScale } from './../../_shared/get-element-scale.js';
import { normalize } from './../../_shared/media/image-crop.js';
import { minMax } from './../../tiptap/index.js';

import handleStyles from '../../ricos-common-plugins/statics/styles-scss.js';
import { roundCrop } from '../crop-overlay/crop-geometry.js';
import { IMAGE_VIEWER_SELECTOR } from '../data-hooks.js';
import styles from './crop-edge-handles-scss.js';

type Edge = 'left' | 'right' | 'top' | 'bottom';

const EDGES: Edge[] = ['left', 'right', 'top', 'bottom'];
const MIN_CROP = 0.05;
const PRIMARY_POINTER_BUTTON = 0;
const PRIMARY_BUTTON_MASK = 1;

const getEdges = (alignment?: PluginContainerData_Alignment | null): Edge[] => {
  if (alignment === PluginContainerData_Alignment.LEFT) {
    return ['right', 'top', 'bottom'];
  }

  if (alignment === PluginContainerData_Alignment.RIGHT) {
    return ['left', 'top', 'bottom'];
  }

  return EDGES;
};

export type CropEdgeChange = { crop: ImageData_Crop; widthPx?: number };

type CropEdgeHandlesProps = {
  containerRef: React.RefObject<HTMLElement | null>;
  crop: ImageData_Crop | null;
  alignment?: PluginContainerData_Alignment | null;
  onChange: (next: CropEdgeChange) => void;
  onDraggingChange?: (isDragging: boolean) => void;
};

const handleClasses = {
  right: handleStyles.handlerRight,
  left: handleStyles.handlerLeft,
  top: handleStyles.handlerTop,
  bottom: handleStyles.handlerBottom,
};

/**
 * Edge handles that crop a selected image without zooming: left/right crop symmetrically
 * (centre fixed, display width shrinks with the crop to keep scale); top/bottom crop from the
 * dragged side with the opposite edge anchored. Corners are scaled by the shared resizer.
 */
export const CropEdgeHandles: React.FC<CropEdgeHandlesProps> = ({
  containerRef,
  crop,
  alignment,
  onChange,
  onDraggingChange,
}) => {
  const [draggingEdge, setDraggingEdge] = useState<Edge | null>(null);
  const dragRef = useRef<{
    edge: Edge;
    startX: number;
    startY: number;
    startCrop: Required<ImageData_Crop>;
    boxWidth: number;
    boxHeight: number;
    scaleX: number;
    scaleY: number;
  } | null>(null);

  const stopDragging = useCallback(
    (event?: React.PointerEvent) => {
      const wasDragging = dragRef.current !== null;
      dragRef.current = null;
      setDraggingEdge(null);
      if (wasDragging) {
        onDraggingChange?.(false);
      }

      if (event?.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
    },
    [onDraggingChange]
  );

  const handlePointerDown = useCallback(
    (event: React.PointerEvent, edge: Edge) => {
      if (event.button !== PRIMARY_POINTER_BUTTON) {
        stopDragging();
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      const imageBox = containerRef.current?.querySelector<HTMLElement>(IMAGE_VIEWER_SELECTOR);
      if (!imageBox) {
        return;
      }

      const rect = imageBox?.getBoundingClientRect();
      if (!rect) {
        return;
      }
      const scale = getElementScale(imageBox);
      dragRef.current = {
        edge,
        startX: event.clientX,
        startY: event.clientY,
        startCrop: normalize(crop),
        boxWidth: rect.width / scale.scaleX,
        boxHeight: rect.height / scale.scaleY,
        scaleX: scale.scaleX,
        scaleY: scale.scaleY,
      };
      setDraggingEdge(edge);
      onDraggingChange?.(true);
      event.currentTarget.setPointerCapture(event.pointerId);
    },
    [containerRef, crop, onDraggingChange, stopDragging]
  );

  const handlePointerMove = useCallback(
    (event: React.PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) {
        return;
      }

      if (event.buttons !== PRIMARY_BUTTON_MASK) {
        stopDragging(event);
        return;
      }

      event.preventDefault();
      const { startCrop: c, boxWidth, boxHeight, scaleX, scaleY } = drag;

      if (drag.edge === 'left' || drag.edge === 'right') {
        const widthPerCrop = boxWidth / c.width;
        const dx = (event.clientX - drag.startX) / scaleX;
        const grow = drag.edge === 'right' ? dx : -dx;
        const centerX = c.x + c.width / 2;
        const width = minMax((boxWidth + 2 * grow) / widthPerCrop, MIN_CROP, 1);
        const x = minMax(centerX - width / 2, 0, 1 - width);
        onChange({
          crop: roundCrop({ ...c, x, width }),
          widthPx: Math.round(widthPerCrop * width),
        });
      } else {
        const heightPerCrop = boxHeight / c.height;
        const dy = (event.clientY - drag.startY) / scaleY;
        const newBoxHeight = drag.edge === 'bottom' ? boxHeight + dy : boxHeight - dy;
        const height = minMax(newBoxHeight / heightPerCrop, MIN_CROP, 1);
        const anchoredY = drag.edge === 'bottom' ? c.y : c.y + c.height - height;
        const y = minMax(anchoredY, 0, 1 - height);
        onChange({ crop: roundCrop({ ...c, y, height }) });
      }
    },
    [onChange, stopDragging]
  );

  const handlePointerUp = useCallback(
    (event: React.PointerEvent) => stopDragging(event),
    [stopDragging]
  );

  return (
    <div className={styles.overlay} aria-hidden>
      {getEdges(alignment).map(edge => (
        <div
          key={edge}
          className={handleClasses[edge]}
          data-active={draggingEdge === edge || undefined}
          data-hook={`image-crop-edge-handle-${edge}`}
          onPointerDown={e => handlePointerDown(e, edge)}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          onLostPointerCapture={handlePointerUp}
          onContextMenu={() => stopDragging()}
        />
      ))}
    </div>
  );
};
