import React, { useContext, useMemo, useRef, useState } from 'react';

import { useConverters } from './../../pm-converters/context.js';
import { TIPTAP_FIGURE_TYPE } from './../../ricos-content/consts.js';
import { RicosContext } from './../../ricos-context/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { useEditorProp } from './../../_shared/some-editor-props-context.js';
import type { Node as ProsemirrorNode } from './../../tiptap/pm/model.js';
import { Loader, MediaItemErrorMsg } from './../../ui-components/index.js';

import { getContainerClasses } from '../../_shared/figure/get-container-classes.js';
import { fromPmImageAnyState } from '../converter/from-pm-image-any-state.js';
import { Image as ViewerImage } from '../viewer/image.js';
import { useImageControls } from './use-image-controls.js';

export const Image: React.FC<PluginProps> = ({
  node,
  editor,
  getPos,
  selected,
  updateAttributes,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const converters = useConverters();
  const containerRef = useRef<HTMLDivElement>(null);
  const [isHovering, setIsHovering] = useState(false);

  const selectedFigure = findFigureForImage({ editor, node, getPos });

  const { loading, loadingPercentage, error, tempData } = node.attrs;
  const { src } = node.attrs.image || {};
  const shouldRender = !!tempData || src?.url || src?.id;

  const ricosNode = fromPmImageAnyState(selectedFigure?.toJSON(), converters.fromPmNode);

  const helpers = useEditorProp(s => s.helpers);

  const imageSrc = useMemo(() => {
    if (src?.url) {
      return src.url;
    }
    if (src?.id && helpers?.getImageUrl) {
      return helpers.getImageUrl({ file_name: src.id });
    }
    return undefined;
  }, [src?.url, src?.id, helpers?.getImageUrl]);

  const { cropMode, enterCropMode, imageControls } = useImageControls({
    containerRef,
    editor,
    nodeAttrs: node.attrs,
    selected,
    isHovering,
    isMobile,
    imageSrc,
    loading,
    error,
    updateAttributes,
  });

  return selectedFigure && ricosNode && shouldRender ? (
    <div
      ref={containerRef}
      className={getContainerClasses(editor, node.attrs.id, isMobile)}
      style={{ position: 'relative' }}
      draggable={!cropMode}
      data-drag-handle
      onPointerEnter={() => setIsHovering(true)}
      onPointerLeave={() => setIsHovering(false)}
      onDoubleClick={enterCropMode}
    >
      <ViewerImage
        isMobile={isMobile}
        node={ricosNode}
        dataUrl={tempData}
        imageClickActionConfig={{ type: 'regular' }}
        shouldLazyLoadImages={false}
        helpers={helpers}
        optimizeCroppedSource={false}
      />
      {imageControls}
      {loading && <Loader type={'medium'} percent={loadingPercentage} />}
      {error && <MediaItemErrorMsg error={error} t={t} />}
    </div>
  ) : null;
};

function findFigureForImage({
  editor,
  node,
  getPos,
}: {
  editor: PluginProps['editor'];
  node: PluginProps['node'];
  getPos?: PluginProps['getPos'];
}): ProsemirrorNode | null {
  if (getPos) {
    try {
      const pos: number = getPos();
      const doc = editor.state.doc;
      const $pos = doc.resolve(pos);

      for (let depth = $pos.depth; depth >= 0; depth--) {
        const parent: ProsemirrorNode = $pos.node(depth);
        if (parent.type.name === TIPTAP_FIGURE_TYPE) {
          return parent;
        }
      }
    } catch {
      // Fallback to full-document scan below
    }
  }

  const figures = editor.$nodes(TIPTAP_FIGURE_TYPE);
  const figureNodeWithImageId = figures?.find(nodePos => {
    return nodePos.node.firstChild?.attrs.id === node.attrs.id;
  });

  return figureNodeWithImageId?.node ?? null;
}
