/**
 * Build the LAYOUT JSON used to replace a figure when converting an image
 * to a banner. Padding starts at the banner default; once attached, the
 * user-set padding persists across banner toggles.
 */
const createImageBannerLayoutContent = (
  position: 'TOP' | 'BOTTOM',
  backdropImage: LayoutData['backgroundImage']
): PmLayoutNode => ({
  type: TIPTAP_LAYOUT_TYPE,
  attrs: {
    containerData: {},
    gap: LAYOUT_DEFAULTS.gap,
    cellPadding: [...LAYOUT_DEFAULTS.cellPadding],
    responsivenessBehaviour: LAYOUT_DEFAULTS.responsivenessBehaviour,
    responsivenessBreakpoint: LAYOUT_DEFAULTS.responsivenessBreakpoint,
    designTarget: LAYOUT_DEFAULTS.designTarget,
    id: generateId(),
    banner: { position, origin: 'IMAGE' },
    backdropImage,
    backdropPaddingTop: DEFAULT_BANNER_VERTICAL_SPACING,
    backdropPaddingBottom: DEFAULT_BANNER_VERTICAL_SPACING,
    backgroundColor: TRANSPARENT_HEX_COLOR,
    backdropColor: TRANSPARENT_HEX_COLOR,
  },
  content: [
    {
      type: TIPTAP_LAYOUT_CELL_TYPE,
      attrs: {
        id: generateId(),
        colSpan: 12,
      },
      content: [
        {
          type: Node_Type.PARAGRAPH,
          attrs: {
            id: generateId(),
            indentation: null,
            level: null,
            textStyle: null,
            style: null,
          },
          content: [],
        },
      ],
    },
  ],
});

/**
 * Replace a figure with a banner layout, placing the layout into the parent
 * CARD's CARD_HEADER (TOP) or CARD_FOOTER (BOTTOM) wrapper if a card exists.
 * Mirrors the wrapper logic in `setLayoutBanner` so image-to-banner conversions
 * end up in the correct structural slot.
 */
const replaceFigureWithBannerLayout = ({
  tiptapEditor,
  figureId,
  cardId,
  position,
  layoutContent,
}: {
  tiptapEditor: Editor;
  figureId: string;
  cardId: string | undefined;
  position: 'TOP' | 'BOTTOM';
  layoutContent: PmLayoutNode;
}) => {
  const wrapperType = position === 'TOP' ? TIPTAP_CARD_HEADER_TYPE : TIPTAP_CARD_FOOTER_TYPE;

  return tiptapEditor
    .chain()
    .focus()
    .deleteNode(figureId)
    .command(({ tr, commands }) => {
      if (!cardId) {
        const insertPos = position === 'TOP' ? 0 : tr.doc.content.size;
        return commands.insertContentAt(insertPos, layoutContent);
      }

      const card = findNodeById(tr, cardId)[0];
      if (!card) {
        return false;
      }

      let wrapperNode: PmNode | undefined;
      let wrapperPos = -1;
      card.node.forEach((child, offset) => {
        if (child.type.name === wrapperType && !wrapperNode) {
          wrapperNode = child;
          wrapperPos = card.pos + 1 + offset;
        }
      });

      const newWrapper = tr.doc.type.schema.nodeFromJSON({
        type: wrapperType,
        content: [layoutContent],
      });

      if (wrapperNode) {
        tr.replaceWith(wrapperPos, wrapperPos + wrapperNode.nodeSize, newWrapper);
      } else if (position === 'TOP') {
        // Insert at the very start of CARD's content, before CARD_CONTENT.
        tr.insert(card.pos + 1, newWrapper);
      } else {
        // Insert at the very end of CARD's content, just before CARD's closing token.
        tr.insert(card.pos + card.node.nodeSize - 1, newWrapper);
      }
      return true;
    })
    .run();
};

export const getToolbarButtons = (
  config: ImagePluginEditorConfig,
  services: RicosServices
): ToolbarButton[] => {
  const {
    modals,
    context: { isMobile },
  } = services;

  const settings = createSettingsButton({
    modalId: IMAGE_SETTINGS_MODAL_ID,
    showLabel: true,
    command: ({ referenceElement, attributes: { selectedNode } }) => {
      modals?.togglePluginPanel({
        id: IMAGE_SETTINGS_MODAL_ID,
        Component: Settings,
        componentProps: {
          referenceElement,
          nodeId: selectedNode.attrs.id,
          config,
        },
        positioning: {
          referenceElement: resolveImageToolbarPanelReferenceElement(referenceElement),
          placement: 'right-start',
        },
        onClickOutside: {
          on: 'pointerup',
          handler: () => {},
        },
        focusReturnElement: referenceElement,
        isMobile: services.context.isMobile,
      });
    },
  });

  const separator = createSeparator({
    visible: getIsEditImageVisibleResolver(config, services, isMobile),
  });

  const nodeSize = createNodeSizeButton({
    services,
    modalId: IMAGE_BUTTONS.size,
    options: ['SMALL', 'CONTENT', 'FULL_WIDTH', 'ORIGINAL'],
  });

  const nodeAlignment = createNodeAlignmentButton({ services, modalId: IMAGE_BUTTONS.alignment });

  const link = createLinkButton(services);

  const replace = createReplaceButton({
    tooltip: 'ReplaceImageButton_Tooltip',
    command: ({ attributes: { selectedNode }, publicCommands, referenceElement }) => {
      handleImageUpload({
        services,
        config,
        publicCommands,
        nodeId: selectedNode.attrs.id,
        referenceElement,
      });
    },
  });

  const imageEditor: ToolbarButton = {
    id: PLUGIN_TOOLBAR_BUTTON_ID_IMAGE_EDITOR,
    type: 'modal',
    dataHook: PLUGIN_TOOLBAR_IMAGE_EDITOR_BUTTON,
    icon: Edit,
    label: 'ImageEditorButton_Label',
    tooltip: 'ImageEditorButton_Tooltip',
    command: ({ attributes: { selectedNode } }) => {
      modals?.openModal({
        Component: ImageEditorModal,
        id: IMAGE_EDITOR_MODAL_ID,
        componentProps: {
          nodeId: selectedNode.attrs.id,
          src: selectedNode.attrs?.image?.src?.id,
          config,
        },
        positioning: { placement: 'top' },
        layout: 'fullscreen',
      });
    },
    renderer: toolbarItem => <ImageEditorButton toolbarItem={toolbarItem} />,
    attributes: {
      visible: getIsEditImageVisibleResolver(config, services, isMobile),
      selectedNode: getNodeInSelection,
    },
  };

  const shapeCrop = createSettingsButton({
    buttonId: PLUGIN_TOOLBAR_BUTTON_ID_SHAPE_CROP,
    modalId: IMAGE_BUTTONS.shapeCrop,
    icon: Crop,
    tooltip: 'ImageShapeCrop_Tooltip',
    dataHook: PLUGIN_TOOLBAR_SHAPE_CROP_BUTTON,
    attributes: {
      visible: () => !services.context.isMobile,
    },
    command: ({ modals, tiptapEditor, attributes }) => {
      const nodeId = attributes.selectedNode?.attrs.id;
      if (!nodeId) {
        return;
      }

      if (modals.isModalOpen(IMAGE_BUTTONS.shapeCrop)) {
        modals.closeModal(IMAGE_BUTTONS.shapeCrop);
        return;
      }

      const meta: ImageCropModeMeta = { nodeId };
      tiptapEditor.view.dispatch(
        tiptapEditor.state.tr.setMeta(IMAGE_CROP_MODE_META, meta).setMeta('addToHistory', false)
      );
    },
  });

  const animation = createAnimationButton(services);

  const deleteButton = createDeleteButton({
    command: data => {
      const figures = data.tiptapEditor.$nodes(TIPTAP_FIGURE_TYPE);
      const selectedFigure = figures?.find(f => {
        return f.firstChild?.node.attrs.id === data.attributes.selectedNode.attrs.id;
      });

      if (selectedFigure) {
        data.tiptapEditor.chain().focus().deleteNode(selectedFigure.attributes.id).run();
      }
    },
  });

  const setAsHeader: ToolbarButton = {
    id: PLUGIN_TOOLBAR_BUTTON_ID_SET_AS_BANNER,
    type: 'toggle',
    icon: Banner,
    tooltip: 'Layouts_LayoutSetAsBanner_Tooltip',
    attributes: {
      selectedNode: getNodeInSelection,
      visible: canSetAsBanner,
    },
    dataHook: PLUGIN_TOOLBAR_SET_AS_HEADER_BUTTON,
    renderer: toolbarItem => <ImageSetAsHeaderButton toolbarItem={toolbarItem} />,
    command: ({ tiptapEditor, attributes: { selectedNode } }) => {
      const imageData = selectedNode.attrs.image;
      if (!imageData) {
        return;
      }

      // Find and delete the FIGURE wrapper containing the image
      const figures = tiptapEditor.$nodes(TIPTAP_FIGURE_TYPE);
      const selectedFigure = figures?.find(f => {
        return f.firstChild?.node.attrs.id === selectedNode.attrs.id;
      });

      if (!selectedFigure) {
        return;
      }

      // Create backdrop image from the image data
      const backdropImage: LayoutData['backgroundImage'] = {
        media: {
          src: imageData.src,
          width: imageData.width,
          height: imageData.height,
        },
        opacity: 100,
        scaling: 'COVER',
        position: 'CENTER',
      };
      // Preload
      if (backdropImage.media?.src?.id) {
        const backgroundImage = new Image();
        backgroundImage.src = getImageUrl(backdropImage.media);
      }

      const layoutContent = createImageBannerLayoutContent('TOP', backdropImage);

      // Delete the figure and place the new banner layout in the parent
      // CARD's CARD_HEADER slot (or at doc root if there's no parent card).
      const cardId = findParentCardId(tiptapEditor.state.doc, selectedFigure.pos);
      replaceFigureWithBannerLayout({
        tiptapEditor,
        figureId: selectedFigure.attributes.id,
        cardId,
        position: 'TOP',
        layoutContent,
      });
    },
  };

  const setAsFooter: ToolbarButton = {
    id: PLUGIN_TOOLBAR_BUTTON_ID_SET_AS_FOOTER,
    type: 'toggle',
    icon: Footer,
    tooltip: 'Layouts_LayoutSetAsFooter_Tooltip',
    attributes: {
      selectedNode: getNodeInSelection,
      visible: canSetAsFooter,
    },
    dataHook: PLUGIN_TOOLBAR_SET_AS_FOOTER_BUTTON,
    renderer: toolbarItem => <ImageSetAsFooterButton toolbarItem={toolbarItem} />,
    command: ({ tiptapEditor, attributes: { selectedNode } }) => {
      const imageData = selectedNode.attrs.image;
      if (!imageData) {
        return;
      }

      const figures = tiptapEditor.$nodes(TIPTAP_FIGURE_TYPE);
      const selectedFigure = figures?.find(f => {
        return f.firstChild?.node.attrs.id === selectedNode.attrs.id;
      });

      if (!selectedFigure) {
        return;
      }

      const backdropImage: LayoutData['backgroundImage'] = {
        media: {
          src: imageData.src,
          width: imageData.width,
          height: imageData.height,
        },
        opacity: 100,
        scaling: 'COVER',
        position: 'CENTER',
      };
      if (backdropImage.media?.src?.id) {
        const backgroundImage = new Image();
        backgroundImage.src = getImageUrl(backdropImage.media);
      }

      const layoutContent = createImageBannerLayoutContent('BOTTOM', backdropImage);

      const cardId = findParentCardId(tiptapEditor.state.doc, selectedFigure.pos);
      replaceFigureWithBannerLayout({
        tiptapEditor,
        figureId: selectedFigure.attributes.id,
        cardId,
        position: 'BOTTOM',
        layoutContent,
      });
    },
  };

  if (services.context.environment === 'wixel') {
    return [
      settings,
      setAsHeader,
      setAsFooter,
      link,
      replace,
      shapeCrop,
      nodeSize,
      nodeAlignment,
      animation,
      deleteButton,
    ];
  }

  return [
    settings,
    separator,
    setAsHeader,
    setAsFooter,
    nodeSize,
    nodeAlignment,
    link,
    replace,
    shapeCrop,
    imageEditor,
    animation,
    separator,
    deleteButton,
  ];
};

const getIsEditImageVisibleResolver =
  (
    config: ImagePluginEditorConfig,
    services: Pick<RicosServices, 'wixInstance'>,
    isMobile: boolean
  ) =>
  () =>
    config.imageEditor && Boolean(services.wixInstance()?.uid) && !isMobile;

// The image-side button is always in the "set" state (an image isn't itself
// a banner), so isActive is false here — the function-form tooltip resolves
// to the "Set as ..." key. The "Remove as ..." case is handled by the
// matching layout-side button after the conversion completes.
const ImageSetAsHeaderButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  const onClick = toolbarItem.commands.click;
  const tooltip = toolbarItem.presentation.tooltip;
  const tooltipKey = typeof tooltip === 'function' ? tooltip({ isActive: false }) : tooltip;

  return (
    <ToolbarButtonComponent
      prefix={Banner}
      onClick={() => onClick?.()}
      dataHook={PLUGIN_TOOLBAR_SET_AS_HEADER_BUTTON}
      label={t(tooltipKey)}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};

const ImageSetAsFooterButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  const onClick = toolbarItem.commands.click;
  const tooltip = toolbarItem.presentation.tooltip;
  const tooltipKey = typeof tooltip === 'function' ? tooltip({ isActive: false }) : tooltip;

  return (
    <ToolbarButtonComponent
      prefix={Footer}
      onClick={() => onClick?.()}
      dataHook={PLUGIN_TOOLBAR_SET_AS_FOOTER_BUTTON}
      label={t(tooltipKey)}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
