import classNames from 'classnames';
import React, { useContext, useMemo } from 'react';

import { RicosContext, RicosViewerContext } from './../../ricos-context/index.js';
import type { ImageNode } from './../../ricos-schema/next-schema/index.js';
import type { Helpers, SEOSettings } from './../../ricos-types/index.js';
import { getCroppedImage } from './../../_shared/media/get-cropped-image.js';
import { isCropped } from './../../_shared/media/image-crop.js';
import { createUserDomainPlaceholder } from './../../_shared/media/user-domain-placeholder.js';
import { resolveDocumentColorToCss } from './../../_shared/theme-color-token.js';
import { Image as ImageComp } from './../../ui-components/Components/image.js';

import { RICOS_DEFAULTS } from '../consts.js';
import { EXPAND_BUTTON, IMAGE_VIEWER_DATA_HOOK_PREFIX } from '../data-hooks.js';
import { expand as ExpandIcon } from '../icons/expand.js';
import { getShapeCropMaskDataUri } from '../shape-crop-mask-data.js';
import classes from '../statics/styles/image-viewer-scss.js';
import type { ImagePluginViewerConfig } from '../types.js';
import type { ImageClickActionConfig, ImageClickActionHandle } from './common-types.js';
import { getCropRenderData } from './get-crop-render-data.js';
import { ImageContainer } from './image-container.js';
import { useCustomWidthStyle } from './use-custom-width-style.js';
import { useExpandButtonFits } from './use-expand-button-fits.js';
import { useFallbackWidthStyle } from './use-fallback-width-style.js';
import { useImageDimensions } from './use-image-dimensions.js';
import { useImageSocialAttributes } from './use-image-social-attributes.js';

type ImageViewerProps = {
  node: ImageNode;
  isMobile: boolean;
  imageClickActionConfig: ImageClickActionConfig;
  shouldLazyLoadImages: boolean;
  helpers?: Helpers;
  config?: ImagePluginViewerConfig;
  expand?: ImageClickActionHandle;
  className?: string;
  dataUrl?: string;
  seoMode?: SEOSettings;
  optimizeCroppedSource?: boolean;
};

export const Image = ({
  dataUrl,
  node,
  className,
  config,
  helpers,
  isMobile,
  seoMode,
  imageClickActionConfig,
  expand,
  shouldLazyLoadImages,
  optimizeCroppedSource = true,
}: ImageViewerProps) => {
  const containerData = node.imageData?.containerData || RICOS_DEFAULTS.containerData;
  const {
    image,
    altText = toCaptionPlainText(node as ImageNode) || '',
    decorative,
    styles,
  } = node.imageData || {};
  const { src } = image || {};

  const { t } = useContext(RicosContext);
  // Optional chaining: the viewer context is absent in editor/preview trees.
  const userDomainMedia = useContext(RicosViewerContext)?.userDomainMedia;
  const getPlaceholder = useMemo(
    () => createUserDomainPlaceholder(userDomainMedia),
    [userDomainMedia]
  );

  const imageSource = useMemo(() => {
    if (dataUrl) {
      return dataUrl;
    }

    const { url, id } = src || {};
    if (url) {
      return url;
    }
    const { getImageUrl } = helpers ?? {};

    if (getImageUrl && id) {
      return getImageUrl({ file_name: id });
    }

    return id;
  }, [
    dataUrl,
    node.imageData?.image?.src?.url,
    node.imageData?.image?.src?.id,
    helpers?.getImageUrl,
  ]);

  const shouldOptimizeCroppedSource =
    optimizeCroppedSource && !!src?.id && isCropped(node.imageData?.crop);

  const { width, height } = useImageDimensions({
    src: imageSource,
    containerData,
    image,
    loadMissingDimensions: !shouldOptimizeCroppedSource,
  });

  // When cropped, the aspect-ratio box uses the cropped dimensions.
  const cropRenderData = getCropRenderData({
    crop: node.imageData?.crop,
    naturalWidth: width,
    naturalHeight: height,
  });
  const croppedImage = useMemo(
    () =>
      shouldOptimizeCroppedSource
        ? getCroppedImage({
            mediaId: src?.id,
            sourceWidth: image?.width,
            sourceHeight: image?.height,
            crop: node.imageData?.crop,
          })
        : undefined,
    [shouldOptimizeCroppedSource, src?.id, image?.width, image?.height, node.imageData?.crop]
  );
  const dimWidth = cropRenderData?.width ?? width;
  const dimHeight = cropRenderData?.height ?? height;
  const loadedImageSource = croppedImage?.url ?? src?.id ?? imageSource;
  const loadedImageWidth = croppedImage?.width ?? width;
  const loadedImageHeight = croppedImage?.height ?? height;

  const fallbackWidthStyle = useFallbackWidthStyle({ containerData, isMobile });
  const customWidthStyle = useCustomWidthStyle({ containerData, isMobile, width });
  const socialAttributes = useImageSocialAttributes({
    config,
    src,
    width: image?.width,
    height: image?.height,
  });

  const doDimensionsExist = loadedImageWidth !== undefined && loadedImageHeight !== undefined;
  const cropShapeMask = getShapeCropMaskDataUri(node.imageData?.cropShape);
  const style = cropShapeMask
    ? {
        '--ricos-image-border-radius': '0',
        '--ricos-image-border-width': '0',
        '--ricos-image-border-color': 'unset',
        '--ricos-image-default-border-color': 'unset',
      }
    : {
        ...(isValueSet(styles?.border?.radius)
          ? {
              '--ricos-image-border-radius': styles?.border?.radius
                ? `${styles.border.radius}px`
                : 'unset',
            }
          : {}),
        ...(isValueSet(styles?.border?.width)
          ? {
              '--ricos-image-border-width': styles?.border?.width
                ? `${styles.border.width}px`
                : 'unset',
            }
          : {}),
        ...(isValueSet(styles?.border?.color)
          ? {
              '--ricos-image-border-color': styles?.border?.color
                ? resolveDocumentColorToCss(styles.border.color)
                : 'unset',
            }
          : {}),
        '--ricos-image-default-border-color': config?.colors?.color8 ?? 'unset',
      };

  // Small images can't hold the expand button: it would overflow and, being clipped by the
  // container's `overflow: hidden`, focusing it on click would scroll-shift the image.
  const { boxRef, buttonRef, fits: expandButtonFits } = useExpandButtonFits();

  // Cropped Wix media loads through a pixel crop; other sources keep the CSS clip fallback.
  const boxStyle = {
    // oxlint-disable-next-line no-useless-computed-key
    ['--dim-height' as string]: dimHeight,
    // oxlint-disable-next-line no-useless-computed-key
    ['--dim-width' as string]: dimWidth,
    ...fallbackWidthStyle,
    ...customWidthStyle,
    ...style,
  } as React.CSSProperties;

  const imageLayerStyle = cropShapeMask
    ? {
        WebkitMaskImage: `url("${cropShapeMask}")`,
        maskImage: `url("${cropShapeMask}")`,
        WebkitMaskRepeat: 'no-repeat',
        maskRepeat: 'no-repeat',
        WebkitMaskPosition: 'center',
        maskPosition: 'center',
        WebkitMaskSize: 'contain',
        maskSize: 'contain',
        WebkitMaskMode: 'alpha',
        maskMode: 'alpha',
      }
    : undefined;

  const imageComp = doDimensionsExist && loadedImageSource && (
    <ImageComp
      id={loadedImageSource}
      containerId={node.id}
      displayMode="fill"
      isFluidLayout
      width={loadedImageWidth}
      height={loadedImageHeight}
      uri={loadedImageSource}
      alt={decorative ? '' : altText}
      role={decorative ? 'presentation' : undefined}
      containerProps={{
        className: classes.cropFullLayer,
        containerId: node.id,
        style:
          cropRenderData && !croppedImage
            ? cropRenderData.fullImageStyle
            : {
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
              },
      }}
      imageStyles={{
        maxWidth: '100%',
        position: 'absolute',
        left: 0,
        top: 0,
      }}
      socialAttrs={{ ...socialAttributes, draggable: false }}
      isSEOBot={!!seoMode}
      encoding={config?.encoding}
      getPlaceholder={getPlaceholder}
      {...(shouldLazyLoadImages
        ? {
            placeholderTransition: seoMode ? undefined : 'blur',
            shouldUseLQIP: config?.disableTransition !== false,
          }
        : {})}
    />
  );

  return (
    <ImageContainer {...imageClickActionConfig} disableDownload={node.imageData?.disableDownload}>
      {imageComp && (
        <div
          ref={boxRef}
          className={classNames(classes.imageWrapper, classes.cropClip, className, {
            [classes.pointer]: !!expand,
          })}
          style={boxStyle}
          data-hook={`${IMAGE_VIEWER_DATA_HOOK_PREFIX}-${node.id}`}
        >
          <div className={classes.imageLayer} style={imageLayerStyle}>
            {imageComp}
          </div>
        </div>
      )}
      {!!expand && expandButtonFits && (
        <button
          ref={buttonRef}
          className={classes.expandButton}
          onClick={expand}
          onKeyDown={e => {
            if (e.key === 'Enter' || e.key === ' ') {
              expand(e);
            }
          }}
          type="button"
          data-hook={EXPAND_BUTTON}
          aria-label={t('Image_Expand_Button_AriaLabel')}
        >
          <ExpandIcon className={classes.expandIcon} />
        </button>
      )}
    </ImageContainer>
  );
};

const toCaptionPlainText = (imageNode: ImageNode) => {
  if (!imageNode.nodes?.[0]?.nodes?.length) {
    return '';
  }

  return imageNode.nodes[0].nodes
    .map(node => ('textData' in node ? node.textData.text : ''))
    .join('');
};

const isValueSet = (value: number | string | null | undefined) => {
  return value !== undefined && value !== null && value !== '';
};
