import { Tabs } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import {
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import { IMAGE_EDITOR_COLOR_PICKER_MODAL_ID, IMAGE_SETTINGS_MODAL_ID } from '../consts.js';
import { SETTINGS_IMAGE_TABS, SETTINGS_MODAL } from '../data-hooks.js';
import classes from '../statics/styles/settings-modal-scss.js';
import { getShapeCrop } from '../toolbar/shape-crop.js';
import type { ImagePluginEditorConfig } from '../types.js';
import { DesignTab } from './design-tab.js';
import { SettingsTab } from './settings-tab.js';

export const ImageTabValue = {
  SETTINGS: 'settings',
  DESIGN: 'design',
} as const;

type ImageTab = (typeof ImageTabValue)[keyof typeof ImageTabValue];

interface SettingsProps {
  nodeId: string;
  config: ImagePluginEditorConfig;
  referenceElement: HTMLElement | undefined;
  initialTab?: ImageTab;
}

export const Settings: FC<SettingsProps> = ({
  nodeId,
  config,
  referenceElement,
  initialTab = ImageTabValue.SETTINGS,
}) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext) || {};
  const containerEl = usePanelContainerElement();
  const { pmNodeAttrs, patchPmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.IMAGE);
  const [activeTab, setActiveTab] = useState(initialTab);

  const isColorPickerModalOpen = () => modalService.isModalOpen(IMAGE_EDITOR_COLOR_PICKER_MODAL_ID);

  const closeModal = () => modalService.closeModal(IMAGE_SETTINGS_MODAL_ID);

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;

      if (referenceElement?.contains(target as Node)) {
        return;
      }

      closeModal();
    },
    disable: isColorPickerModalOpen(),
  });

  if (!pmNodeAttrs) {
    logInvariant(new Error('Image settings: node attrs not found'));
    return null;
  }

  const hasCropShape = Boolean(getShapeCrop(pmNodeAttrs));
  const visibleTab = hasCropShape ? ImageTabValue.SETTINGS : activeTab;

  return (
    <Panel
      closeButtonProps={{ onClick: () => modalService.closeModal(IMAGE_SETTINGS_MODAL_ID) }}
      dataHook={SETTINGS_MODAL}
    >
      <PanelHeader title={t('ImageSettings_Header')} />

      {!hasCropShape && (
        <Tabs
          dataHook={SETTINGS_IMAGE_TABS}
          className={classes.tabs}
          size="small"
          alignment="center"
          type="uniformFull"
          minWidth={0}
          activeId={activeTab}
          onClick={value => setActiveTab(value.id as ImageTab)}
          items={[
            { id: ImageTabValue.SETTINGS, title: t('ImagePlugin_Settings_Tab_Settings') },
            { id: ImageTabValue.DESIGN, title: t('ImagePlugin_Settings_Tab_Design') },
          ]}
        />
      )}

      {visibleTab === ImageTabValue.SETTINGS && (
        <SettingsTab pmNodeAttrs={pmNodeAttrs} patchPmNodeAttrs={patchPmNodeAttrs} />
      )}

      {visibleTab === ImageTabValue.DESIGN && (
        <DesignTab
          pmNodeAttrs={pmNodeAttrs}
          patchPmNodeAttrs={patchPmNodeAttrs}
          nodeId={nodeId}
          config={config}
        />
      )}
    </Panel>
  );
};
