import React from 'react';

import type { Direction, Rect } from './crop-geometry.js';
import styles from './crop-overlay-scss.js';

const HANDLES: Direction[] = [
  'topLeft',
  'top',
  'topRight',
  'right',
  'bottomRight',
  'bottom',
  'bottomLeft',
  'left',
];

const CORNERS: Direction[] = ['topLeft', 'topRight', 'bottomLeft', 'bottomRight'];
const isCorner = (direction: Direction): boolean => CORNERS.includes(direction);

type CropFrameProps = {
  frame: Rect;
  activeDirection: Direction | null;
  locked?: boolean;
  onHandlePointerDown: (direction: Direction, event: React.PointerEvent) => void;
  onMovePointerDown: (event: React.PointerEvent) => void;
};

/** The crop window: a draggable body plus resize handles. */
export const CropFrame: React.FC<CropFrameProps> = ({
  frame,
  activeDirection,
  locked = false,
  onHandlePointerDown,
  onMovePointerDown,
}) => {
  const handles = locked ? CORNERS : HANDLES;

  return (
    <div
      className={styles.frame}
      data-hook="image-crop-frame"
      style={{ left: frame.x, top: frame.y, width: frame.width, height: frame.height }}
      onPointerDown={onMovePointerDown}
    >
      <div className={styles.frameGrid} aria-hidden />
      {handles.map(direction => (
        <div
          key={direction}
          className={styles.handle}
          data-direction={direction}
          data-active={activeDirection === direction || undefined}
          data-hook={`image-crop-handle-${direction}`}
          onPointerDown={event => onHandlePointerDown(direction, event)}
        >
          {isCorner(direction) && (
            <svg className={styles.bracket} viewBox="0 0 20 20" aria-hidden>
              <path className={styles.bracketBorder} d="M16 4H6a2 2 0 0 0-2 2v10" />
              <path className={styles.bracketBody} d="M16 4H6a2 2 0 0 0-2 2v10" />
            </svg>
          )}
        </div>
      ))}
    </div>
  );
};
