import { Edit } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';

interface Props {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}

export const ImageEditorButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { t } = useContext(RicosContext) || {};
  const [referenceElement, setReferenceElement] = React.useState<HTMLElement | null>(null);

  return (
    <ToolbarButton
      ref={setReferenceElement}
      prefix={Edit}
      onClick={() => toolbarItem.commands.click({ referenceElement })}
      dataHook={dataHook}
      ariaLabel={t('ImageEditorButton_Tooltip')}
      tooltip={t('ImageEditorButton_Tooltip')}
      disabled={!toolbarItem.attributes?.selectedNode?.attrs.image?.src?.id}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
