import { Box, Button, Loader, SidePanel } from '@wix/design-system';
import React, { Suspense, useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { Panel, PanelHeader } from './../../ui-components/index.js';

import type { CropPresetId, CropPresetOption } from './crop-presets.js';
import styles from './shape-crop-modal-scss.js';

const CropPresetGrid = React.lazy(
  () => import(/* webpackChunkName: "ricos_imageShapeCropGrid" */ './crop-preset-grid.js')
);

export type ShapeCropModalProps = {
  selectedId: CropPresetId;
  onApply: (preset: CropPresetOption) => void;
  onApplyCrop: () => void;
  onCancelCrop: () => void;
};

export const ShapeCropModal: React.FC<ShapeCropModalProps> = ({
  selectedId,
  onApply,
  onApplyCrop,
  onCancelCrop,
}) => {
  const { t } = useContext(RicosContext);
  const [currentSelectedId, setCurrentSelectedId] = useState(selectedId);

  useEffect(() => {
    setCurrentSelectedId(selectedId);
  }, [selectedId]);

  return (
    <Panel
      closeButtonProps={{
        onClick: onCancelCrop,
      }}
      dataHook="image-shape-crop-modal"
    >
      <PanelHeader title={t('ImageShapeCrop_Title')} />

      <SidePanel.Content noPadding>
        <div className={styles.content}>
          {/* The placeholder matches the loaded grid's height so the panel doesn't
              resize — and therefore doesn't re-anchor — once the chunk arrives. */}
          <Suspense
            fallback={
              <div className={styles.gridPlaceholder}>
                <Loader size="small" />
              </div>
            }
          >
            <CropPresetGrid
              selectedId={currentSelectedId}
              onSelect={option => {
                setCurrentSelectedId(option.id);
                onApply(option);
              }}
            />
          </Suspense>
        </div>
      </SidePanel.Content>

      <SidePanel.Footer showDivider>
        <Box align="right" gap="SP2">
          <Button
            priority="secondary"
            size="small"
            onClick={onCancelCrop}
            dataHook="image-shape-crop-modal-cancel"
          >
            {t('ImageCrop_Cancel')}
          </Button>
          <Button
            priority="primary"
            size="small"
            onClick={onApplyCrop}
            dataHook="image-shape-crop-modal-apply"
          >
            {t('ImageCrop_Apply')}
          </Button>
        </Box>
      </SidePanel.Footer>
    </Panel>
  );
};
