import { Box, Input } from '@wix/design-system';
import React, { useContext, useRef } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  ZIndexContext,
} from './../../ricos-context/index.js';
import { toHexFormat } from './../../ricos-styles/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmImageNode } from './../../_shared/pm-node-types.js';
import { BorderColorPicker } from './../components/border-color-picker.js';
import {
  ColorWithOpacityInput,
  NumberInputWithLabel,
} from './../../ui-components/index.js';

import { IMAGE_EDITOR_COLOR_PICKER_MODAL_ID, IMAGE_SETTINGS_MODAL_ID } from '../consts.js';
import {
  SETTINGS_DESIGN_TAB_BORDER_COLOR_PICKER,
  SETTINGS_DESIGN_TAB_BORDER_WIDTH_INPUT,
  SETTINGS_DESIGN_TAB_CORNER_RADIUS_INPUT,
} from '../data-hooks.js';
import type { ImagePluginEditorConfig } from '../types.js';

type Props = {
  pmNodeAttrs: PmImageNode['attrs'];
  patchPmNodeAttrs: (data: Partial<PmImageNode['attrs']>) => void;
  nodeId: string;
  config: ImagePluginEditorConfig;
};

export const DesignTab = ({ pmNodeAttrs, patchPmNodeAttrs, nodeId, config }: Props) => {
  const { t, isMobile } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext) || {};
  const { adapter } = useContext(EditorContext);
  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const colorPickerRef = useRef<HTMLDivElement>(null);

  const logBi = useBiNext({ modalId: IMAGE_SETTINGS_MODAL_ID, pluginId: 'image', nodeId });

  const image = nodeId
    ? adapter.tiptapEditor.view.dom.querySelector(`[data-hook=image-viewer-${nodeId}`)
    : undefined;
  const imageStyle = image ? window.getComputedStyle(image) : undefined;

  const customImageBorderColor = imageStyle?.getPropertyValue('--ricos-custom-image-border-color');
  const customImageBorderColorHex = customImageBorderColor
    ? toHexFormat(customImageBorderColor)
    : '#000000';

  const borderColorValue =
    pmNodeAttrs.styles?.border.color ?? customImageBorderColorHex.toUpperCase();

  const borderRadiusValue =
    pmNodeAttrs.styles?.border.radius ??
    parseToInt(imageStyle?.getPropertyValue('border-radius')) ??
    0;

  const borderWidthValue =
    pmNodeAttrs.styles?.border.width ??
    parseToInt(imageStyle?.getPropertyValue('border-width')) ??
    0;

  const openColorPicker = () => {
    const modalId = IMAGE_EDITOR_COLOR_PICKER_MODAL_ID;
    const referenceElement = colorPickerRef.current ?? undefined;

    modalService.togglePluginPanel({
      id: modalId,
      Component: BorderColorPicker,
      componentProps: {
        modalId,
        nodeId,
        referenceElement,
        config,
        defaultColor: borderColorValue,
        onColorSelected: color =>
          patchPmNodeAttrs({
            styles: {
              border: {
                color: color ?? pmNodeAttrs.styles?.border?.color,
                radius: pmNodeAttrs.styles?.border.radius,
                width: pmNodeAttrs.styles?.border.width,
              },
            },
          }),
        onColorAdded: config.onBorderColorAdded,
      },
      isMobile,
      positioning: {
        referenceElement,
        placement: 'left',
      },
      type: undefined,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      focusReturnElement: referenceElement ?? undefined,
    });
  };

  return (
    <Box direction="vertical" gap="SP2" overflow="auto" paddingTop="SP3" paddingBottom="SP3">
      <Box direction="vertical" gap="SP2" paddingLeft="SP3" paddingRight="SP3">
        <ColorWithOpacityInput
          label={t('ImagePlugin_Design_Border_Color')}
          inputDataHook={SETTINGS_DESIGN_TAB_BORDER_COLOR_PICKER}
          fill={{
            type: 'color',
            color: borderColorValue,
            onChange: color => {
              logBi({ dataHook: SETTINGS_DESIGN_TAB_BORDER_COLOR_PICKER, value: color });
              patchPmNodeAttrs({
                styles: {
                  border: {
                    ...pmNodeAttrs.styles?.border,
                    color,
                  },
                },
              });
            },
          }}
          onColorPress={openColorPicker}
          colorPickerRef={colorPickerRef}
          zIndex={zIndex}
        />

        <NumberInputWithLabel
          label={t('ImagePlugin_Design_Border_Width')}
          dataHook={SETTINGS_DESIGN_TAB_BORDER_WIDTH_INPUT}
          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
          value={borderWidthValue}
          min={0}
          max={15}
          onChange={width => {
            patchPmNodeAttrs({
              styles: {
                border: {
                  ...pmNodeAttrs.styles?.border,
                  width,
                },
              },
            });
          }}
          logBi={logBi}
          zIndex={zIndex}
        />

        <NumberInputWithLabel
          label={t('ImagePlugin_Design_Corner_Radius')}
          dataHook={SETTINGS_DESIGN_TAB_CORNER_RADIUS_INPUT}
          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
          value={borderRadiusValue}
          min={0}
          max={300}
          onChange={radius =>
            patchPmNodeAttrs({
              styles: {
                border: {
                  ...pmNodeAttrs.styles?.border,
                  radius,
                },
              },
            })
          }
          logBi={logBi}
          zIndex={zIndex}
        />
      </Box>
    </Box>
  );
};

const parseToInt = (value: string | undefined): number | undefined => {
  if (value === undefined) {
    return undefined;
  }

  const parsedValue = parseInt(value);
  return isNaN(parsedValue) ? undefined : parsedValue;
};
