import { FLOATING_PLUGIN_TOOLBAR } from './../../toolbars-v3/index.js';

type VirtualReferenceElement = {
  getBoundingClientRect: () => DOMRect;
  closest: (selector: string) => Element | null;
  contains: (other: Node | null) => boolean;
};

export type ImagePluginPanelReferenceElement = HTMLElement | VirtualReferenceElement;

export const resolveImageToolbarPanelReferenceElement = (
  referenceElement: HTMLElement | null | undefined
): HTMLElement | null | undefined =>
  referenceElement?.closest<HTMLElement>(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
  referenceElement;

export const createStaticImagePanelReferenceElement = (
  referenceElement: ImagePluginPanelReferenceElement | null | undefined
): ImagePluginPanelReferenceElement | null | undefined => {
  if (!referenceElement) {
    return referenceElement;
  }

  const rect = referenceElement.getBoundingClientRect();
  const staticRect = new DOMRect(rect.x, rect.y, rect.width, rect.height);

  return {
    getBoundingClientRect: () => staticRect,
    closest: () => null,
    contains: () => false,
  };
};

export const resolveImageDoubleClickPanelReferenceElement = ({
  referenceElement,
  environment,
  portal,
}: {
  referenceElement: HTMLElement;
  environment?: string;
  portal: HTMLElement | null;
}): ImagePluginPanelReferenceElement => {
  if (environment === 'wixel') {
    return createWixelPanelReferenceElement();
  }

  const closestToolbar = referenceElement?.closest<HTMLElement>(
    `[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`
  );

  if (closestToolbar) {
    return closestToolbar;
  }

  return (
    portal?.querySelector<HTMLElement>(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
    referenceElement
  );
};

const createWixelPanelReferenceElement = (): VirtualReferenceElement => {
  const defaultRect = new DOMRect(70, 48, 60, 0);

  return {
    getBoundingClientRect: () => defaultRect,
    closest: () => null,
    contains: () => false,
  };
};
